SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Table structure for agent_run
-- ----------------------------
DROP TABLE IF EXISTS `agent_run`;
CREATE TABLE `agent_run`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自检运行ID',
  `run_no` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '自检运行唯一编号',
  `minutes_id` int NOT NULL COMMENT '被自检的会议纪要ID',
  `meeting_id` int NOT NULL COMMENT '所属会议ID',
  `user_id` int NOT NULL COMMENT '发起人用户ID',
  `model_config_id` int NOT NULL COMMENT '自检模型配置ID',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RUNNING' COMMENT 'RUNNING、WAITING_CONFIRMATION、SUCCEEDED、REJECTED、FAILED、INTERRUPTED',
  `stage` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '等待执行' COMMENT '当前执行阶段',
  `progress` int NOT NULL DEFAULT 0 COMMENT '自检进度百分比',
  `current_round` int NOT NULL DEFAULT 0 COMMENT '已完成的反思轮次',
  `max_rounds` int NOT NULL DEFAULT 2 COMMENT '反思轮次上限，一轮等于审查一次加改一版',
  `passed` tinyint(1) NOT NULL DEFAULT 0 COMMENT '最后一轮模型是否判定通过',
  `score` int NOT NULL DEFAULT 0 COMMENT '最后一轮的自检得分',
  `issue_count` int NOT NULL DEFAULT 0 COMMENT '最后一轮剩余的问题条数',
  `review_json` json NOT NULL COMMENT '最后一轮的问题清单',
  `revised_json` json NULL COMMENT '待人工确认的修订稿，为空表示纪要一个字都没改',
  `applied_by` int NULL DEFAULT NULL COMMENT '确认人用户ID',
  `applied_time` datetime NULL DEFAULT NULL COMMENT '确认时间',
  `reject_reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '人工放弃修订的原因',
  `final_result` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '自检结论',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '运行失败原因',
  `started_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '开始时间',
  `finished_at` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_agent_run_no`(`run_no` ASC) USING BTREE,
  INDEX `idx_agent_run_user_time`(`user_id` ASC, `started_at` ASC) USING BTREE,
  INDEX `idx_agent_run_status`(`status` ASC) USING BTREE,
  INDEX `idx_agent_run_minutes_status`(`minutes_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '会议纪要自检运行表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of agent_run
-- ----------------------------
INSERT INTO `agent_run` VALUES (3, 'AGRD8DDDB538CB148DFBFAC9ADF0FE14332', 3, 2, 1, 5, 'SUCCEEDED', '等待人工确认', 100, 2, 2, 0, 60, 5, '[{\"field\": \"decisions\", \"index\": -1, \"detail\": \"原文明确‘知识索引构建期间资料变化时，由资料维护人完成整理后重新构建’，该操作规则未在topics、decisions或risks中任何位置体现，属于会议达成的明确行动共识，应记入decisions或topics。\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"新增决策项：\'知识索引构建期间若发生资料更新，须由资料维护人完成全部整理后，统一发起重建流程，确保索引一致性。\'\"}, {\"field\": \"decisions\", \"index\": -1, \"detail\": \"原文明确‘发布首周，每天查看运行观测和质量评价数据，发现任务逾期、模型调用失败率升高或员工反馈集中时，及时形成跟进报告’，该动作性要求未进入decisions或pending_items，仅在summary中模糊提及‘设定...机制’，无具体执行主体和交付物。\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"新增决策项：\'发布首周每日17:00前，由王工牵头汇总运行观测中心与质量评价数据，形成《AI会议助手首周运行日报》，重点标注任务逾期率突增、模型失败率>2%、员工集中反馈TOP3问题，并同步至张晨、赵敏、周宁。\'\"}, {\"field\": \"risks\", \"index\": 2, \"detail\": \"risks中第三项‘任务负责人分配不合理风险’的suggestion为空，但原文明确‘Agent可以结合员工当前任务负载提出负责人建议，但创建正式任务前仍由用户确认’，应补充可操作建议。\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"补充suggestion：\'前端在任务创建页增加‘负责人负载提示’，展示建议人选当前待办任务数及平均处理时长，辅助用户决策。\'\"}, {\"field\": \"decisions\", \"index\": 5, \"detail\": \"decisions中张晨负责的首周复盘任务，content仅笼统写‘用于观察模型输出是否满足业务需要’，未落实原文‘质量评价页面还会收集纪要和agent结果的综合评分，准确性、完整性和可执行性评分’这一具体交付要求，无法验证是否完成。\", \"issue_type\": \"NOT_ACTIONABLE\", \"suggestion\": \"将content中‘以及纪要与Agent结果的准确性、完整性、可执行性评分’改为‘并在质量评价页面导出《纪要与Agent结果三维度评分报表》（含准确性、完整性、可执行性单项分及综合分），于9月8日18:00前提交。\'\"}, {\"field\": \"summary\", \"index\": -1, \"detail\": \"summary称‘识别并定义4项关键风险（含2项高风险）’，但risks列表含3项HIGH（模型延迟、负责人分配、删除用户）和1项MEDIUM（资料更新），与原文‘阻断任务未完成时的专项评审机制’被明确定义为‘风险等级为高’不符，且该机制未作为独立风险项列出，导致风险数量与等级描述错误。\", \"issue_type\": \"UNSUPPORTED\", \"suggestion\": \"修改summary为‘识别并定义5项关键风险（含4项高风险）’，并在risks中新增第5项：\'阻断任务未按时完成将触发发布时间调整风险\'，level: HIGH，suggestion: \'按pending_items约定，由张晨与王工于8月31日17:00召开专项评审。\'\"}]', '{\"risks\": [{\"level\": \"HIGH\", \"content\": \"模型服务延迟波动导致纪要生成与Agent运行等待时间延长，影响用户体验。\", \"suggestion\": \"发布首周每日查看运行观测中心的调用量、失败率、平均耗时和token使用量。\"}, {\"level\": \"MEDIUM\", \"content\": \"会议资料频繁更新导致知识索引长期处于‘需要重建’状态，影响检索时效性与一致性。\", \"suggestion\": \"建议资料整理完成后统一发起知识索引构建。\"}, {\"level\": \"HIGH\", \"content\": \"任务负责人分配不合理风险：Agent仅提供建议，最终由用户确认，存在人为误配可能；无技术强制校验机制。\", \"suggestion\": \"前端在任务创建页增加‘负责人负载提示’，展示建议人选当前待办任务数及平均处理时长，辅助用户决策。\"}, {\"level\": \"HIGH\", \"content\": \"删除用户时若关联历史业务记录（会议、任务、转写、纪要、问答、Agent运行、质量评价），系统将阻止删除操作，影响账号生命周期管理。\", \"suggestion\": \"管理员须先调整相关业务记录中的负责人、创建人或协作人关系，确保人员信息可追溯。\"}, {\"level\": \"HIGH\", \"content\": \"阻断任务未按时完成将触发发布时间调整风险\", \"suggestion\": \"按pending_items约定，由张晨与王工于8月31日17:00召开专项评审。\"}], \"topics\": [{\"title\": \"上一轮产品灰度发布的数据复盘\", \"summary\": \"复盘8月20日至26日灰度发布数据，覆盖10%-30%活跃用户，评估登录成功率、核心下单链路成功率、新功能访问与转化提升、用户反馈高频问题、权限控制验证及数据安全性。\"}, {\"title\": \"9月1日正式发布的功能范围和风险\", \"summary\": \"明确9月1日正式发布功能范围，包括会议创建与状态流转、资料管理、音视频转写、AI纪要、任务跟踪、知识库、React Agent分析、运行观测与质量评价；同步确认移动端附件下载问题须修复并写入发布说明。\"}, {\"title\": \"明确发布前后的任务负责人、协作人和完成期限\", \"summary\": \"确定发布前后各项任务的责任人、协作人与完成期限，涵盖移动端修复、回归测试、运营公告、客服知识库建设、首周数据复盘等五类关键事项。\"}], \"summary\": \"本次会议完成AI智能会议助手灰度发布复盘，确认核心功能稳定、权限合规、主流程可用；明确9月1日9:00正式发布，覆盖会议全生命周期与AI任务跟踪能力；识别并定义5项关键风险（含4项高风险），落实7项关键任务及责任人与截止时间；设定首周数据复盘框架与运营支持机制；约定阻断任务未完成时的专项评审机制。\", \"decisions\": [{\"basis\": \"灰度发布数据显示核心链路成功率高（登录99.8%，下单99.2%），无数据丢失、权限越界或重复提交问题；权限控制与预期一致；模型调用成功率97.9%-98.6%，失败可重试；主流程和边界场景已验证通过。\", \"content\": \"同意于9月1日9:00正式发布AI智能会议助手与任务跟踪系统，发布范围包括会议创建和状态流转、会议资料管理、音视频转写、AI纪要、任务跟踪、会议知识库、React Agent数据分析、运行观测和质量评价。\", \"owner_suggestion\": \"全体负责人\", \"deadline_suggestion\": \"2023-09-01T09:00:00\"}, {\"basis\": \"移动端附件下载进度未刷新问题影响发布当天支持成本，且已在灰度中被用户集中反馈；研发计划今日完成接口与前端验证。\", \"content\": \"移动端附件下载进度问题须在发布前修复，并在发布说明中写明处理结果。\", \"owner_suggestion\": \"王工（后端负责人）\", \"deadline_suggestion\": \"2023-08-30T18:00:00\"}, {\"basis\": \"测试团队已完成主流程及三类边界场景验证，但需补充两组验收数据以覆盖长音频与多角色说话人匹配场景。\", \"content\": \"发布前须完成两组补充验收：①至少30分钟真实会议录音，验证长音频切分、异步进度与长文本纪要合并；②含多个角色发言的会议内容，验证说话人标签与员工身份匹配效果。\", \"owner_suggestion\": \"陈琳（测试负责人）\", \"deadline_suggestion\": \"2023-08-31T12:00:00\"}, {\"basis\": \"运营需支撑上线后数据观察与用户引导，客服需快速定位问答来源以提升响应质量。\", \"content\": \"运营负责人赵敏牵头，协作人周宁，于9月1日9:00前完成发布公告与部门通知。\", \"owner_suggestion\": \"赵敏（运营负责人）\", \"deadline_suggestion\": \"2023-09-01T09:00:00\"}, {\"basis\": \"运营需支撑上线后数据观察与用户引导，客服需快速定位问答来源以提升响应质量。\", \"content\": \"客户支持负责人周宁牵头，协作人赵敏，于9月1日10:00前完成常见问题知识库建设。\", \"owner_suggestion\": \"周宁（客户支持负责人）\", \"deadline_suggestion\": \"2023-09-01T10:00:00\"}, {\"basis\": \"张晨提出首周复盘需结构化追踪五类核心数据，质量评价页面已支持综合评分采集。\", \"content\": \"产品负责人张晨负责发布决策复盘与首周数据汇总，重点分析会议创建数量与总时长、转写任务成功率与平均耗时、已确认纪要/任务草稿/正式任务数量、任务完成率与逾期率、RAG问答调用量/Agent运行次数/工具调用成功率/人工确认次数，并在质量评价页面导出《纪要与Agent结果三维度评分报表》（含准确性、完整性、可执行性单项分及综合分），于9月8日18:00前提交。\", \"owner_suggestion\": \"张晨（产品负责人）\", \"deadline_suggestion\": \"2023-09-08T18:00:00\"}, {\"basis\": \"知识索引构建期间资料变化时，由资料维护人完成整理后重新构建，该操作规则为会议明确达成的行动共识。\", \"content\": \"知识索引构建期间若发生资料更新，须由资料维护人完成全部整理后，统一发起重建流程，确保索引一致性。\", \"owner_suggestion\": \"资料维护人\", \"deadline_suggestion\": \"2023-09-01T09:00:00\"}, {\"basis\": \"发布首周每日查看运行观测和质量评价数据，发现任务逾期、模型调用失败率升高或员工反馈集中时，及时形成跟进报告，该动作性要求为会议明确共识。\", \"content\": \"发布首周每日17:00前，由王工牵头汇总运行观测中心与质量评价数据，形成《AI会议助手首周运行日报》，重点标注任务逾期率突增、模型失败率>2%、员工集中反馈TOP3问题，并同步至张晨、赵敏、周宁。\", \"owner_suggestion\": \"王工（后端负责人）\", \"deadline_suggestion\": \"2023-09-01T17:00:00\"}], \"viewpoints\": [{\"speaker\": \"张晨\", \"viewpoint\": \"灰度期间整体登录成功率为99.8%，核心下单链路成功率为99.2%；会议任务看板访问量提升24%，任务完成凭证上传率提升18%；用户集中反馈两个问题：①部分用户不知如何从会议纪要进入任务草稿；②移动端弱网下附件下载进度未及时刷新；已确认无数据丢失、权限越界或订单重复提交；四类账号权限控制符合预期；移动端附件下载体验问题需在正式发布前完成处理。\"}, {\"speaker\": \"王工\", \"viewpoint\": \"灰度期间后端接口无500错误；会议纪要模型调用成功率为98.6%（平均耗时7.8秒），Agent工具调用成功率为97.9%；两次失败源于外部模型服务短暂超时，系统已保存失败原因并支持用户重试；所有会议相关数据（转写、纪要、知识索引、Agent运行记录）均存于MySQL；知识索引更新时旧版本仍可检索，直至新版本切换完成；当前RE返回结构已包含引用会议名称、来源类型、时间点和原文片段。\"}, {\"speaker\": \"陈琳\", \"viewpoint\": \"已完成会议创建、参会人维护、音视频上传转写、说话人匹配、纪要修订、任务草稿确认、延期转交、RE问答、Agent人工确认及运行中断恢复等主流程验证；三类边界场景验证通过：①无权限访问返回明确提示；②仅草稿与已确认版本可导出；③已完成任务不可修改进度或发送提醒；需补充两组验收数据：①≥30分钟真实会议录音；②多角色发言会议用于验证说话人标签匹配效果；测试团队将于8月31日12:00前完成回归并提交凭证。\"}, {\"speaker\": \"赵敏\", \"viewpoint\": \"建议增加两项发布后观察指标：①员工从会议纪要创建正式任务的转化率；②任务逾期率；上线后一周内按部门统计会议数量、时长、任务完成率、逾期率及高频问题；逾期任务详情页展示提醒记录；每日16:00汇总高风险任务并同步至部门负责人与客服负责人；客服关注知识问答引用是否清晰（需含会议名称、来源类型、时间点、原文片段）。\"}, {\"speaker\": \"周宁\", \"viewpoint\": \"客服侧需在常见问题知识库中覆盖账号登录、会议权限、资料上传、格式转写失败、重试、纪要导出、任务负责人调整、知识索引状态、Agent人工确认等内容；对无法复现问题，需记录会议编号、任务编号或Agent运行编号以便研发追踪。\"}], \"pending_items\": [{\"content\": \"当移动端附件下载进度任务（负责人王工，截止8月30日18:00）或发布回归任务（负责人陈琳，截止8月31日12:00）任一未按时完成时，触发专项评审：由张晨与王工于8月31日17:00召开专项评审，决定是否调整发布时间。\", \"owner_suggestion\": \"张晨、王工\", \"deadline_suggestion\": \"2023-08-31T17:00:00\"}]}', 1, '2026-09-16 10:40:29', NULL, '已按审查发现的 5 条问题重写纪要，得分 60，达到 2 轮上限后没有再复审，请人工判断是否采用修订稿。', NULL, '2026-09-16 02:35:48', '2026-09-16 10:38:18', '2026-09-16 10:40:29');
INSERT INTO `agent_run` VALUES (4, 'AGRE1FF10D55F9047DFBF5562655A0EEDD9', 4, 2, 1, 5, 'SUCCEEDED', '等待人工确认', 100, 2, 2, 0, 40, 8, '[{\"field\": \"summary\", \"index\": -1, \"detail\": \"summary未提及会议结尾明确复述的三项结论（V2.0按期发布+灰度三步走+通稿定稿时间）及\'行动项有三个\'的量化表述，也未体现会议闭环特征（\'我复述一遍\'、\'今天就到这里散会\'）\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"补充：\'会议最终形成三项结论：V2.0按期发布（报表导出入口隐藏）、灰度分三阶段实施（10%→50%→100%）、对外通稿与产品公告于发布前一日18:00前定稿；明确三项行动项及责任人。\'\"}, {\"field\": \"topics\", \"index\": 0, \"detail\": \"topics中\'V2.0能否按期发布\'议题摘要未包含\'消息推送免打扰设置已修复并昨日回归通过\'这一关键验收进展，该信息直接影响\'能否按期发布\'的判断依据\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"在该议题summary中补充：\'消息推送免打扰设置已修复并通过回归测试，仅报表导出存在性能瓶颈需延迟上线。\'\"}, {\"field\": \"viewpoints\", \"index\": 1, \"detail\": \"viewpoints中张涛的发言未记录\'缓存方案被否决\'这一关键决策过程，原文明确\'缓存覆盖不全，用户选冷门区间还是慢\'，该信息是选择异步方案的核心依据\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"在张涛viewpoint中补充：\'缓存方案因无法覆盖冷门时间区间被否决，异步方案为唯一可行解。\'\"}, {\"field\": \"decisions\", \"index\": 3, \"detail\": \"decisions第四条将\'张涛周三给进度\'这一风险监控动作错误列为正式决策，原文中这是主持人提出的风险应对措施（\'这个风险记下来\'），且决策主体是会议共识而非张涛单方承诺\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"删除该条decision，相关内容应归入risks模块，并明确标注为\'主持人提出的风险应对机制\'。\"}, {\"field\": \"pending_items\", \"index\": 2, \"detail\": \"pending_items中\'报表导出异步化改造完成并上线验证\'的deadline写为\'本周五下班前\'，但原文明确\'开发两天，连调一天，测试两天，加起来一周\'，且主持人说\'本周五前完成\'，未限定\'下班前\'；\'上线验证\'在原文中无对应表述，属UNSUPPORTED添加\", \"issue_type\": \"UNSUPPORTED\", \"suggestion\": \"修正为：\'报表导出异步化改造（含开发、联调、测试）于本周五前完成\'，删除\'上线验证\'。\"}, {\"field\": \"pending_items\", \"index\": 0, \"detail\": \"pending_items中所有条目owner_suggestion字段使用\'suggestion\'后缀，不符合\'必须明确指定负责人\'的可落实要求，原文中均为直接指派（\'张涛负责\'、\'陈磊明天下班前提交\'、\'刘颖负责通稿定稿\'）\", \"issue_type\": \"NOT_ACTIONABLE\", \"suggestion\": \"将\'owner_suggestion\'统一改为\'owner\'，值为\'张涛\'、\'陈磊\'、\'刘颖\'。\"}, {\"field\": \"pending_items\", \"index\": 0, \"detail\": \"pending_items中\'灰度期间值班排班表制定与发布\'的deadline写为\'会议次日18:00前\'，但原文明确\'明天下班前\'，\'下班前\'是弹性时间点，\'18:00前\'属过度精确且无依据\", \"issue_type\": \"VAGUE\", \"suggestion\": \"修正为\'明天下班前\'，与原文完全一致。\"}, {\"field\": \"risks\", \"index\": 0, \"detail\": \"risks中未记录原文明确提出的\'异步改造和灰度发布挨得太近\'这一原话风险描述，仅泛化为\'排期过近\'，丢失关键语境\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"在risks content中补充原话：\'异步改造和灰度发布挨得太近\'。\"}]', '{\"risks\": [{\"level\": \"MEDIUM\", \"content\": \"报表导出异步化改造与灰度发布排期过近，若改造延期可能影响整体发布节奏或迫使功能延至下一版本。异步改造和灰度发布挨得太近。\", \"suggestion\": \"张涛须周三反馈中期进度；若未完成联调，则报表导出推至下个版本。主持人提出的风险应对机制。\"}], \"topics\": [{\"title\": \"V2.0能否按期发布\", \"summary\": \"评估V2.0版本是否具备按期发布条件，重点聚焦17个计划需求的验收状态及剩余两个未闭环问题（报表导出、消息推送免打扰）的解决进展。消息推送免打扰设置已修复并通过回归测试，仅报表导出存在性能瓶颈需延迟上线。\"}, {\"title\": \"灰度发布策略\", \"summary\": \"确定灰度发布的范围、节奏、技术实现方式（分流维度）、监控指标及回滚能力，确保平稳过渡。\"}, {\"title\": \"对外通稿与产品公告安排\", \"summary\": \"明确对外传播材料（通稿、产品公告）的内容边界、发布时间、协同节奏及定稿节点，确保信息与实际功能一致。\"}], \"summary\": \"本次会议围绕V2.0产品发布评审展开，确认核心功能验收基本完成，但报表导出存在性能瓶颈（40+秒超时、高失败率），决定发布时隐藏该功能入口；灰度采用分三阶段（10%→50%→100%）、用户ID取模分流、完备回滚方案；对外通稿须删减报表导出内容，并于发布前一日18:00前定稿；对外通稿与产品公告将于发布当天上午10:00同步发布；会议最终形成三项结论：V2.0按期发布（报表导出入口隐藏）、灰度分三阶段实施（10%→50%→100%）、对外通稿与产品公告于发布前一日18:00前定稿；明确三项行动项及责任人。\", \"decisions\": [{\"basis\": \"报表导出接口在压测中单用户导出三个月数据耗时40+秒，超网关30秒限制，500并发下失败率达12%，当前方案无法满足发布质量要求；异步改造需一周，无法在发布前完成。\", \"content\": \"V2.0按原计划时间发布，报表导出功能入口在发布时隐藏，待异步改造完成后单独上线。\", \"owner_suggestion\": \"张涛\", \"deadline_suggestion\": \"发布当日\"}, {\"basis\": \"灰度需兼顾稳定性与可观测性，且数据库改动均向后兼容，回滚成本低、速度快（5分钟）。\", \"content\": \"灰度分三阶段执行：首日10%流量、次日50%、第三日全量；按用户ID取模分流，确保用户一致性；回滚预案已就绪。\", \"owner_suggestion\": \"陈磊\", \"deadline_suggestion\": \"发布起连续三天\"}, {\"basis\": \"对外通稿需与实际发布功能严格一致，报表导出功能将被隐藏，故相关内容须删除；产品公告与通稿同步于发布当天上午10点发出，需预留审核时间。\", \"content\": \"对外通稿及产品公告定稿时间为发布前一日下午6点前，通稿中删除报表导出相关描述。对外通稿与产品公告均于发布当天上午10:00同步发布。\", \"owner_suggestion\": \"刘颖\", \"deadline_suggestion\": \"发布前一日下午6点前\"}], \"viewpoints\": [{\"speaker\": \"王敏\", \"viewpoint\": \"V2.0计划内17个需求已验收通过15个，剩余报表导出和消息推送免打扰设置两项；后者已修复并昨日回归通过\"}, {\"speaker\": \"张涛\", \"viewpoint\": \"报表导出压测暴露单用户导出三个月数据耗时40+秒、超网关30秒限制，500并发失败率12%；提出异步任务方案（导出返回任务号、后台生成、通知下载），需开发2天+联调1天+测试2天共5个工作日；用户体验优于缓存方案；缓存方案因无法覆盖冷门时间区间被否决，异步方案为唯一可行解。\"}, {\"speaker\": \"陈磊\", \"viewpoint\": \"系统容量充足（可支撑8万DAU，预估发布后5万）；灰度建议分三步（10%→50%→100%），按用户ID取模分流；监控核心指标为接口错误率、平均响应时间、核心链路转化率；回滚预案完备，数据库改动向后兼容，5分钟内可切回旧版；灰度期间需安排值班盯盘，排班表将于明天下班前发出；已配置三项核心指标告警，超阈值直接发至工作群\"}, {\"speaker\": \"刘颖\", \"viewpoint\": \"对外通稿初稿已完成，需根据最终功能清单调整；因报表导出将隐藏，通稿中对应段落需删除；建议发布当天上午10点同步发布通稿与产品公告。\"}], \"pending_items\": [{\"content\": \"灰度期间值班排班表制定与发布\", \"owner_suggestion\": \"陈磊\", \"deadline_suggestion\": \"明天下班前\"}, {\"content\": \"报表导出异步化改造中期进度同步（周三反馈联调是否完成）\", \"owner_suggestion\": \"张涛\", \"deadline_suggestion\": \"本周三\"}, {\"content\": \"报表导出异步化改造（含开发、联调、测试）于本周五前完成\", \"owner_suggestion\": \"张涛\", \"deadline_suggestion\": \"本周五前\"}]}', 1, '2026-09-16 10:40:23', NULL, '已按审查发现的 8 条问题重写纪要，得分 40，达到 2 轮上限后没有再复审，请人工判断是否采用修订稿。', NULL, '2026-09-16 02:37:02', '2026-09-16 10:39:10', '2026-09-16 10:40:23');

-- ----------------------------
-- Table structure for agent_step
-- ----------------------------
DROP TABLE IF EXISTS `agent_step`;
CREATE TABLE `agent_step`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '自检步骤ID',
  `run_id` int NOT NULL COMMENT '自检运行ID',
  `step_no` int NOT NULL COMMENT '运行内步骤号',
  `round_no` int NOT NULL DEFAULT 0 COMMENT '所属反思轮次',
  `step_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'REVIEW、REFINE、FINAL',
  `decision_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '这一步要做什么',
  `observation_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '这一步的结论，审查步里是问题清单',
  `payload_json` json NULL COMMENT '这一步的结构化产物，审查步是打分和问题，重写步是新纪要',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'RUNNING' COMMENT 'RUNNING、SUCCEEDED、FAILED',
  `elapsed_ms` bigint NOT NULL DEFAULT 0 COMMENT '步骤耗时毫秒',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '步骤失败原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `finish_time` datetime NULL DEFAULT NULL COMMENT '完成时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_agent_run_step`(`run_id` ASC, `step_no` ASC) USING BTREE,
  INDEX `idx_agent_step_run_status`(`run_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '会议纪要自检步骤表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of agent_step
-- ----------------------------
INSERT INTO `agent_step` VALUES (11, 3, 1, 1, 'REVIEW', '第1轮：审查是否可落实', '纪要整体结构完整、关键信息覆盖全面，但存在1处遗漏（风险中未记录‘任务负责人分配不合理’的应对建议原文细节）、2处可落实性缺陷（1项决策未明确协作人，1项待确认事项未写明触发条件），另有1处UNSUPPORTED表述。经综合评估，扣分后得分为94。\n风险与争议第3条｜转写原文里找不到依据：原文中张晨明确指出：\'Agent可以结合员工当前任务负载提出负责人建议，但创建正式任务前仍由用户确认\'，而risks中第三条仅写\'加强创建任务环节的负载提示与推荐置信度展示\'，该建议在原文中并未出现，属于编造。 → 建议：应删除\'加强创建任务环节的负载提示与推荐置信度展示\'，改为客观转述原文：\'Agent仅提供建议，最终由用户确认，存在人为误配可能；无技术强制校验机制。\'\n决策第4条｜没有明确负责人：decisions第4条中\'运营团队于9月1日9:00前完成发布公告与部门通知；客户支持团队于9月1日10:00前完成常见问题知识库建设\'，原文明确赵敏为负责人、周宁为协作人，且两项任务分工不同（赵敏主责公告，周宁主责知识库），但该决策将二者合并为同一责任主体，未区分各自职责边界。 → 建议：拆分为两条独立决策：①运营负责人赵敏牵头，协作人周宁，于9月1日9:00前完成发布公告与部门通知；②客户支持负责人周宁牵头，协作人赵敏，于9月1日10:00前完成常见问题知识库建设。\n待确认事项第1条｜表述含糊：pending_items中\'若移动端附件下载进度任务或发布回归任务未能按时完成，是否调整发布时间需由张晨与王工于8月31日17:00召开专项评审决定\'，原文明确\'如果任意阻断任务没有完成，由张晨和王工在8月31日下午五点召开专项评审，决定是否调整发布时间\'，但纪要未说明\'阻断任务\'具体指哪几项——原文明确定义为\'移动端附件下载进度任务和发布回归任务\'，且强调\'前提是这两项任务按时完成\'，该前提条件未在pending_items中体现。 → 建议：补充触发条件：\'当移动端附件下载进度任务（负责人王工，截止8月30日18:00）或发布回归任务（负责人陈琳，截止8月31日12:00）任一未按时完成时，触发专项评审。\'\n风险与争议第3条｜转写原文里找不到依据：risks中第三条\'任务负责人分配不合理风险\'的content描述为\'Agent仅提供建议，最终由用户确认\'，符合原文；但suggestion中\'加强创建任务环节的负载提示与推荐置信度展示\'在原文中完全未提及，属纪要员自行添加，破坏客观性。 → 建议：删除该建议，或标注为\'后续优化建议（非本次会议结论）\'。', '{\"score\": 94, \"issues\": [{\"field\": \"risks\", \"index\": 2, \"detail\": \"原文中张晨明确指出：\'Agent可以结合员工当前任务负载提出负责人建议，但创建正式任务前仍由用户确认\'，而risks中第三条仅写\'加强创建任务环节的负载提示与推荐置信度展示\'，该建议在原文中并未出现，属于编造。\", \"issue_type\": \"UNSUPPORTED\", \"suggestion\": \"应删除\'加强创建任务环节的负载提示与推荐置信度展示\'，改为客观转述原文：\'Agent仅提供建议，最终由用户确认，存在人为误配可能；无技术强制校验机制。\'\"}, {\"field\": \"decisions\", \"index\": 3, \"detail\": \"decisions第4条中\'运营团队于9月1日9:00前完成发布公告与部门通知；客户支持团队于9月1日10:00前完成常见问题知识库建设\'，原文明确赵敏为负责人、周宁为协作人，且两项任务分工不同（赵敏主责公告，周宁主责知识库），但该决策将二者合并为同一责任主体，未区分各自职责边界。\", \"issue_type\": \"MISSING_OWNER\", \"suggestion\": \"拆分为两条独立决策：①运营负责人赵敏牵头，协作人周宁，于9月1日9:00前完成发布公告与部门通知；②客户支持负责人周宁牵头，协作人赵敏，于9月1日10:00前完成常见问题知识库建设。\"}, {\"field\": \"pending_items\", \"index\": 0, \"detail\": \"pending_items中\'若移动端附件下载进度任务或发布回归任务未能按时完成，是否调整发布时间需由张晨与王工于8月31日17:00召开专项评审决定\'，原文明确\'如果任意阻断任务没有完成，由张晨和王工在8月31日下午五点召开专项评审，决定是否调整发布时间\'，但纪要未说明\'阻断任务\'具体指哪几项——原文明确定义为\'移动端附件下载进度任务和发布回归任务\'，且强调\'前提是这两项任务按时完成\'，该前提条件未在pending_items中体现。\", \"issue_type\": \"VAGUE\", \"suggestion\": \"补充触发条件：\'当移动端附件下载进度任务（负责人王工，截止8月30日18:00）或发布回归任务（负责人陈琳，截止8月31日12:00）任一未按时完成时，触发专项评审。\'\"}, {\"field\": \"risks\", \"index\": 2, \"detail\": \"risks中第三条\'任务负责人分配不合理风险\'的content描述为\'Agent仅提供建议，最终由用户确认\'，符合原文；但suggestion中\'加强创建任务环节的负载提示与推荐置信度展示\'在原文中完全未提及，属纪要员自行添加，破坏客观性。\", \"issue_type\": \"UNSUPPORTED\", \"suggestion\": \"删除该建议，或标注为\'后续优化建议（非本次会议结论）\'。\"}], \"passed\": false}', 'SUCCEEDED', 19124, NULL, '2026-09-16 02:35:48', '2026-09-16 10:36:08');
INSERT INTO `agent_step` VALUES (12, 3, 2, 1, 'REFINE', '第1轮：按 4 条问题重写', '已按 4 条问题重写', '{\"risks\": [{\"level\": \"HIGH\", \"content\": \"模型服务延迟波动导致纪要生成与Agent运行等待时间延长，影响用户体验。\", \"suggestion\": \"发布首周每日查看运行观测中心的调用量、失败率、平均耗时和token使用量。\"}, {\"level\": \"MEDIUM\", \"content\": \"会议资料频繁更新导致知识索引长期处于‘需要重建’状态，影响检索时效性与一致性。\", \"suggestion\": \"建议资料整理完成后统一发起知识索引构建。\"}, {\"level\": \"HIGH\", \"content\": \"任务负责人分配不合理风险：Agent仅提供建议，最终由用户确认，存在人为误配可能；无技术强制校验机制。\", \"suggestion\": \"\"}, {\"level\": \"HIGH\", \"content\": \"删除用户时若关联历史业务记录（会议、任务、转写、纪要、问答、Agent运行、质量评价），系统将阻止删除操作，影响账号生命周期管理。\", \"suggestion\": \"管理员须先调整相关业务记录中的负责人、创建人或协作人关系，确保人员信息可追溯。\"}], \"topics\": [{\"title\": \"上一轮产品灰度发布的数据复盘\", \"summary\": \"复盘8月20日至26日灰度发布数据，覆盖10%-30%活跃用户，评估登录成功率、核心下单链路成功率、新功能访问与转化提升、用户反馈高频问题、权限控制验证及数据安全性。\"}, {\"title\": \"9月1日正式发布的功能范围和风险\", \"summary\": \"明确9月1日正式发布功能范围，包括会议创建与状态流转、资料管理、音视频转写、AI纪要、任务跟踪、知识库、React Agent分析、运行观测与质量评价；同步确认移动端附件下载问题须修复并写入发布说明。\"}, {\"title\": \"明确发布前后的任务负责人、协作人和完成期限\", \"summary\": \"确定发布前后各项任务的责任人、协作人与完成期限，涵盖移动端修复、回归测试、运营公告、客服知识库建设、首周数据复盘等五类关键事项。\"}], \"summary\": \"本次会议完成AI智能会议助手灰度发布复盘，确认核心功能稳定、权限合规、主流程可用；明确9月1日9:00正式发布，覆盖会议全生命周期与AI任务跟踪能力；识别并定义4项关键风险（含2项高风险），落实5项关键任务及责任人与截止时间；设定首周数据复盘框架与运营支持机制；约定阻断任务未完成时的专项评审机制。\", \"decisions\": [{\"basis\": \"灰度发布数据显示核心链路成功率高（登录99.8%，下单99.2%），无数据丢失、权限越界或重复提交问题；权限控制与预期一致；模型调用成功率97.9%-98.6%，失败可重试；主流程和边界场景已验证通过。\", \"content\": \"同意于9月1日9:00正式发布AI智能会议助手与任务跟踪系统，发布范围包括会议创建和状态流转、会议资料管理、音视频转写、AI纪要、任务跟踪、会议知识库、React Agent数据分析、运行观测和质量评价。\", \"owner_suggestion\": \"全体负责人\", \"deadline_suggestion\": \"2023-09-01T09:00:00\"}, {\"basis\": \"移动端附件下载进度未刷新问题影响发布当天支持成本，且已在灰度中被用户集中反馈；研发计划今日完成接口与前端验证。\", \"content\": \"移动端附件下载进度问题须在发布前修复，并在发布说明中写明处理结果。\", \"owner_suggestion\": \"王工（后端负责人）\", \"deadline_suggestion\": \"2023-08-30T18:00:00\"}, {\"basis\": \"测试团队已完成主流程及三类边界场景验证，但需补充两组验收数据以覆盖长音频与多角色说话人匹配场景。\", \"content\": \"发布前须完成两组补充验收：①至少30分钟真实会议录音，验证长音频切分、异步进度与长文本纪要合并；②含多个角色发言的会议内容，验证说话人标签与员工身份匹配效果。\", \"owner_suggestion\": \"陈琳（测试负责人）\", \"deadline_suggestion\": \"2023-08-31T12:00:00\"}, {\"basis\": \"运营需支撑上线后数据观察与用户引导，客服需快速定位问答来源以提升响应质量。\", \"content\": \"运营负责人赵敏牵头，协作人周宁，于9月1日9:00前完成发布公告与部门通知。\", \"owner_suggestion\": \"赵敏（运营负责人）\", \"deadline_suggestion\": \"2023-09-01T09:00:00\"}, {\"basis\": \"运营需支撑上线后数据观察与用户引导，客服需快速定位问答来源以提升响应质量。\", \"content\": \"客户支持负责人周宁牵头，协作人赵敏，于9月1日10:00前完成常见问题知识库建设。\", \"owner_suggestion\": \"周宁（客户支持负责人）\", \"deadline_suggestion\": \"2023-09-01T10:00:00\"}, {\"basis\": \"张晨提出首周复盘需结构化追踪五类核心数据，质量评价页面已支持综合评分采集。\", \"content\": \"产品负责人张晨负责发布决策复盘与首周数据汇总，重点分析会议创建数量与总时长、转写任务成功率与平均耗时、已确认纪要/任务草稿/正式任务数量、任务完成率与逾期率、RAG问答调用量/Agent运行次数/工具调用成功率/人工确认次数，以及纪要与Agent结果的准确性、完整性、可执行性评分。\", \"owner_suggestion\": \"张晨（产品负责人）\", \"deadline_suggestion\": \"2023-09-08T18:00:00\"}], \"viewpoints\": [{\"speaker\": \"张晨\", \"viewpoint\": \"灰度期间整体登录成功率为99.8%，核心下单链路成功率为99.2%；会议任务看板访问量提升24%，任务完成凭证上传率提升18%；用户集中反馈两个问题：①部分用户不知如何从会议纪要进入任务草稿；②移动端弱网下附件下载进度未及时刷新；已确认无数据丢失、权限越界或订单重复提交；四类账号权限控制符合预期；移动端附件下载体验问题需在正式发布前完成处理。\"}, {\"speaker\": \"王工\", \"viewpoint\": \"灰度期间后端接口无500错误；会议纪要模型调用成功率为98.6%（平均耗时7.8秒），Agent工具调用成功率为97.9%；两次失败源于外部模型服务短暂超时，系统已保存失败原因并支持用户重试；所有会议相关数据（转写、纪要、知识索引、Agent运行记录）均存于MySQL；知识索引更新时旧版本仍可检索，直至新版本切换完成；当前RE返回结构已包含引用会议名称、来源类型、时间点和原文片段。\"}, {\"speaker\": \"陈琳\", \"viewpoint\": \"已完成会议创建、参会人维护、音视频上传转写、说话人匹配、纪要修订、任务草稿确认、延期转交、RE问答、Agent人工确认及运行中断恢复等主流程验证；三类边界场景验证通过：①无权限访问返回明确提示；②仅草稿与已确认版本可导出；③已完成任务不可修改进度或发送提醒；需补充两组验收数据：①≥30分钟真实会议录音；②多角色发言会议用于验证说话人标签匹配效果；测试团队将于8月31日12:00前完成回归并提交凭证。\"}, {\"speaker\": \"赵敏\", \"viewpoint\": \"建议增加两项发布后观察指标：①员工从会议纪要创建正式任务的转化率；②任务逾期率；上线后一周内按部门统计会议数量、时长、任务完成率、逾期率及高频问题；逾期任务详情页展示提醒记录；每日16:00汇总高风险任务并同步至部门负责人与客服负责人；客服关注知识问答引用是否清晰（需含会议名称、来源类型、时间点、原文片段）。\"}, {\"speaker\": \"周宁\", \"viewpoint\": \"客服侧需在常见问题知识库中覆盖账号登录、会议权限、资料上传、格式转写失败、重试、纪要导出、任务负责人调整、知识索引状态、Agent人工确认等内容；对无法复现问题，需记录会议编号、任务编号或Agent运行编号以便研发追踪。\"}], \"pending_items\": [{\"content\": \"当移动端附件下载进度任务（负责人王工，截止8月30日18:00）或发布回归任务（负责人陈琳，截止8月31日12:00）任一未按时完成时，触发专项评审：由张晨与王工于8月31日17:00召开专项评审，决定是否调整发布时间。\", \"owner_suggestion\": \"张晨、王工\", \"deadline_suggestion\": \"2023-08-31T17:00:00\"}]}', 'SUCCEEDED', 46308, NULL, '2026-09-16 02:36:08', '2026-09-16 10:36:54');
INSERT INTO `agent_step` VALUES (13, 3, 3, 2, 'REVIEW', '第2轮：审查是否可落实', '纪要整体结构完整，但存在关键遗漏：原文中明确约定的‘知识索引构建期间资料变化时，由资料维护人完成整理后重新构建’这一操作规则未在任何字段中体现（topics/decisions/risks均未覆盖）；‘发布首周每天查看运行观测和质量评价数据，发现任务逾期、模型调用失败率升高或员工反馈集中时，及时形成跟进报告’这一动作性要求未进入decisions或pending_items；风险项中‘任务负责人分配不合理’缺少应对建议（原文有‘Agent可提供建议但需用户确认’，纪要risks.suggestion为空）；决策项中张晨的首周复盘任务虽列了5类数据，但原文明确要求‘质量评价页面还会收集纪要和agent结果的综合评分，准确性、完整性和可执行性评分’，该评分维度未在decision.content中写实，仅笼统说‘用于观察模型输出是否满足业务需要’，属NOT_ACTIONABLE；此外，summary中‘识别并定义4项关键风险（含2项高风险）’与risks实际列出4项（3项HIGH+1项MEDIUM）矛盾，且原文明确‘阻断任务未完成时的专项评审机制’风险等级为‘高’，但纪要将该机制拆解为pending_items而非作为HIGH风险单列，导致风险归类不准确。综上，存在多处MISSING_ITEM和NOT_ACTIONABLE问题。\n决策整体｜原文里讨论过但纪要漏记：原文明确‘知识索引构建期间资料变化时，由资料维护人完成整理后重新构建’，该操作规则未在topics、decisions或risks中任何位置体现，属于会议达成的明确行动共识，应记入decisions或topics。 → 建议：新增决策项：\'知识索引构建期间若发生资料更新，须由资料维护人完成全部整理后，统一发起重建流程，确保索引一致性。\'\n决策整体｜原文里讨论过但纪要漏记：原文明确‘发布首周，每天查看运行观测和质量评价数据，发现任务逾期、模型调用失败率升高或员工反馈集中时，及时形成跟进报告’，该动作性要求未进入decisions或pending_items，仅在summary中模糊提及‘设定...机制’，无具体执行主体和交付物。 → 建议：新增决策项：\'发布首周每日17:00前，由王工牵头汇总运行观测中心与质量评价数据，形成《AI会议助手首周运行日报》，重点标注任务逾期率突增、模型失败率>2%、员工集中反馈TOP3问题，并同步至张晨、赵敏、周宁。\'\n风险与争议第3条｜原文里讨论过但纪要漏记：risks中第三项‘任务负责人分配不合理风险’的suggestion为空，但原文明确‘Agent可以结合员工当前任务负载提出负责人建议，但创建正式任务前仍由用户确认’，应补充可操作建议。 → 建议：补充suggestion：\'前端在任务创建页增加‘负责人负载提示’，展示建议人选当前待办任务数及平均处理时长，辅助用户决策。\'\n决策第6条｜无法落成可执行任务：decisions中张晨负责的首周复盘任务，content仅笼统写‘用于观察模型输出是否满足业务需要’，未落实原文‘质量评价页面还会收集纪要和agent结果的综合评分，准确性、完整性和可执行性评分’这一具体交付要求，无法验证是否完成。 → 建议：将content中‘以及纪要与Agent结果的准确性、完整性、可执行性评分’改为‘并在质量评价页面导出《纪要与Agent结果三维度评分报表》（含准确性、完整性、可执行性单项分及综合分），于9月8日18:00前提交。\'\n会议摘要整体｜转写原文里找不到依据：summary称‘识别并定义4项关键风险（含2项高风险）’，但risks列表含3项HIGH（模型延迟、负责人分配、删除用户）和1项MEDIUM（资料更新），与原文‘阻断任务未完成时的专项评审机制’被明确定义为‘风险等级为高’不符，且该机制未作为独立风险项列出，导致风险数量与等级描述错误。 → 建议：修改summary为‘识别并定义5项关键风险（含4项高风险）’，并在risks中新增第5项：\'阻断任务未按时完成将触发发布时间调整风险\'，level: HIGH，suggestion: \'按pending_items约定，由张晨与王工于8月31日17:00召开专项评审。\'', '{\"score\": 60, \"issues\": [{\"field\": \"decisions\", \"index\": -1, \"detail\": \"原文明确‘知识索引构建期间资料变化时，由资料维护人完成整理后重新构建’，该操作规则未在topics、decisions或risks中任何位置体现，属于会议达成的明确行动共识，应记入decisions或topics。\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"新增决策项：\'知识索引构建期间若发生资料更新，须由资料维护人完成全部整理后，统一发起重建流程，确保索引一致性。\'\"}, {\"field\": \"decisions\", \"index\": -1, \"detail\": \"原文明确‘发布首周，每天查看运行观测和质量评价数据，发现任务逾期、模型调用失败率升高或员工反馈集中时，及时形成跟进报告’，该动作性要求未进入decisions或pending_items，仅在summary中模糊提及‘设定...机制’，无具体执行主体和交付物。\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"新增决策项：\'发布首周每日17:00前，由王工牵头汇总运行观测中心与质量评价数据，形成《AI会议助手首周运行日报》，重点标注任务逾期率突增、模型失败率>2%、员工集中反馈TOP3问题，并同步至张晨、赵敏、周宁。\'\"}, {\"field\": \"risks\", \"index\": 2, \"detail\": \"risks中第三项‘任务负责人分配不合理风险’的suggestion为空，但原文明确‘Agent可以结合员工当前任务负载提出负责人建议，但创建正式任务前仍由用户确认’，应补充可操作建议。\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"补充suggestion：\'前端在任务创建页增加‘负责人负载提示’，展示建议人选当前待办任务数及平均处理时长，辅助用户决策。\'\"}, {\"field\": \"decisions\", \"index\": 5, \"detail\": \"decisions中张晨负责的首周复盘任务，content仅笼统写‘用于观察模型输出是否满足业务需要’，未落实原文‘质量评价页面还会收集纪要和agent结果的综合评分，准确性、完整性和可执行性评分’这一具体交付要求，无法验证是否完成。\", \"issue_type\": \"NOT_ACTIONABLE\", \"suggestion\": \"将content中‘以及纪要与Agent结果的准确性、完整性、可执行性评分’改为‘并在质量评价页面导出《纪要与Agent结果三维度评分报表》（含准确性、完整性、可执行性单项分及综合分），于9月8日18:00前提交。\'\"}, {\"field\": \"summary\", \"index\": -1, \"detail\": \"summary称‘识别并定义4项关键风险（含2项高风险）’，但risks列表含3项HIGH（模型延迟、负责人分配、删除用户）和1项MEDIUM（资料更新），与原文‘阻断任务未完成时的专项评审机制’被明确定义为‘风险等级为高’不符，且该机制未作为独立风险项列出，导致风险数量与等级描述错误。\", \"issue_type\": \"UNSUPPORTED\", \"suggestion\": \"修改summary为‘识别并定义5项关键风险（含4项高风险）’，并在risks中新增第5项：\'阻断任务未按时完成将触发发布时间调整风险\'，level: HIGH，suggestion: \'按pending_items约定，由张晨与王工于8月31日17:00召开专项评审。\'\"}], \"passed\": false}', 'SUCCEEDED', 26425, NULL, '2026-09-16 02:36:54', '2026-09-16 10:37:20');
INSERT INTO `agent_step` VALUES (14, 4, 1, 1, 'REVIEW', '第1轮：审查是否可落实', '纪要整体结构完整，但存在多处关键信息遗漏、责任人错标、时间点错位及 unsupported 内容，影响任务落地。核心问题包括：viewpoints 中 speaker 姓名与原文严重不符（张晨/李悦 vs 王敏/陈磊/张涛）；decisions 中 owner_suggestion 错将张涛的任务归给张晨；pending_items 漏记‘张涛周五前完成改造’这一明确行动项；risks 中未体现‘周三未完成联调则推至下版本’的刚性决策依据；summary 未体现‘发布当天上午10点同步发通稿与公告’这一关键时间点。\n发言观点第1条｜转写原文里找不到依据：viewpoints 中三位发言人姓名全部错误：原文中汇报功能验收的是王敏，非张晨；汇报灰度的是陈磊，非李悦；市场侧是刘颖，正确；但将张涛的技术方案陈述错误归给张晨，且完全未记录张涛本人观点。 → 建议：应更正为：speaker: \'王敏\'，viewpoint: \'V2.0计划内17个需求已验收通过15个，剩余报表导出和消息推送免打扰设置两项；后者已修复并昨日回归通过\'；新增 speaker: \'张涛\'，viewpoint: \'报表导出压测暴露单用户导出三个月数据耗时40+秒、超网关30秒限制，500并发失败率12%；提出异步任务方案（导出返回任务号、后台生成、通知下载），需开发2天+联调1天+测试2天共5个工作日；用户体验优于缓存方案\'。\n发言观点第2条｜转写原文里找不到依据：viewpoints 中第二条 speaker 错标为\'李悦\'，原文中汇报灰度与容量的是陈磊，且其明确说明\'灰度分三天：10%→50%→全量\'、\'按用户ID取模分流\'、\'回滚最快五分钟\'、\'监控接口错误率/响应时间/核心转化率\'、\'告警直发群\'、\'明天下班前交排班表\'，但纪要未记录后两项关键内容。 → 建议：应更正 speaker 为\'陈磊\'，并在 viewpoint 中补充：\'灰度期间需安排值班盯盘，排班表将于明天下班前发出\'；\'已配置三项核心指标告警，超阈值直接发至工作群\'。\n决策第1条｜转写原文里找不到依据：decisions 第一条 owner_suggestion 错标为\'张晨\'，原文中明确由张涛负责报表导出异步化改造，且会议结论明确\'张涛负责\'，张晨未在原文中发言。 → 建议：owner_suggestion 应修正为\'张涛\'。\n决策第2条｜转写原文里找不到依据：decisions 第二条 owner_suggestion 错标为\'李悦\'，原文中灰度策略全程由陈磊汇报并承诺执行（含排班、监控、回滚），无李悦此人。 → 建议：owner_suggestion 应修正为\'陈磊\'。\n决策第3条｜原文里讨论过但纪要漏记：decisions 第三条 deadline_suggestion 为\'发布前一日下午6点前\'，正确；但 content 中仅写\'通稿及产品公告定稿时间\'，漏记原文关键共识\'通稿和产品公告均于发布当天上午10点同步发出\'，该时间点对市场协同至关重要，属必须记录的决策要素。 → 建议：content 应补充：\'对外通稿与产品公告均于发布当天上午10:00同步发布\'。\n待确认事项整体｜原文里讨论过但纪要漏记：pending_items 仅列出2项，但原文明确三项行动项：①张涛本周五前完成报表导出异步化改造（\'张涛负责报表导出异步化改造，本周五前完成\'）；②陈磊明天下班前提交灰度值班排班表；③刘颖负责通稿定稿（已体现在decisions中，但 pending_items 未单列排班表交付动作）。其中第一项\'周五前完成\'是独立、强约束的待办，未出现在 pending_items 中。 → 建议：应新增 pending_item：content: \'报表导出异步化改造完成并上线验证\'，owner_suggestion: \'张涛\'，deadline_suggestion: \'本周五下班前\'。\n待确认事项第1条｜表述含糊：pending_items 第一项 deadline_suggestion 为\'明天下班前\'，原文中陈磊说\'我明天下班前把排班表发到群里\'，但未明确\'明天\'对应具体日期（如发布前X日），属时间模糊，无法跨日执行。 → 建议：deadline_suggestion 应写为绝对日期，如\'发布前两日18:00前\'（需根据会议召开日推算），或至少标注\'会议次日18:00前\'。\n风险与争议第1条｜原文里讨论过但纪要漏记：risks 中 suggestion 写\'张涛须周三反馈中期进度；若未完成联调，则报表导出推至下个版本\'，但原文中明确决策为\'张涛，你这周三给我一个中期进度，如果到周三还没完成联调，我们就把报表导出推到下个版本\'，该句是会议达成的刚性决策，应放入 decisions 而非 ', '{\"score\": 30, \"issues\": [{\"field\": \"viewpoints\", \"index\": 0, \"detail\": \"viewpoints 中三位发言人姓名全部错误：原文中汇报功能验收的是王敏，非张晨；汇报灰度的是陈磊，非李悦；市场侧是刘颖，正确；但将张涛的技术方案陈述错误归给张晨，且完全未记录张涛本人观点。\", \"issue_type\": \"UNSUPPORTED\", \"suggestion\": \"应更正为：speaker: \'王敏\'，viewpoint: \'V2.0计划内17个需求已验收通过15个，剩余报表导出和消息推送免打扰设置两项；后者已修复并昨日回归通过\'；新增 speaker: \'张涛\'，viewpoint: \'报表导出压测暴露单用户导出三个月数据耗时40+秒、超网关30秒限制，500并发失败率12%；提出异步任务方案（导出返回任务号、后台生成、通知下载），需开发2天+联调1天+测试2天共5个工作日；用户体验优于缓存方案\'。\"}, {\"field\": \"viewpoints\", \"index\": 1, \"detail\": \"viewpoints 中第二条 speaker 错标为\'李悦\'，原文中汇报灰度与容量的是陈磊，且其明确说明\'灰度分三天：10%→50%→全量\'、\'按用户ID取模分流\'、\'回滚最快五分钟\'、\'监控接口错误率/响应时间/核心转化率\'、\'告警直发群\'、\'明天下班前交排班表\'，但纪要未记录后两项关键内容。\", \"issue_type\": \"UNSUPPORTED\", \"suggestion\": \"应更正 speaker 为\'陈磊\'，并在 viewpoint 中补充：\'灰度期间需安排值班盯盘，排班表将于明天下班前发出\'；\'已配置三项核心指标告警，超阈值直接发至工作群\'。\"}, {\"field\": \"decisions\", \"index\": 0, \"detail\": \"decisions 第一条 owner_suggestion 错标为\'张晨\'，原文中明确由张涛负责报表导出异步化改造，且会议结论明确\'张涛负责\'，张晨未在原文中发言。\", \"issue_type\": \"UNSUPPORTED\", \"suggestion\": \"owner_suggestion 应修正为\'张涛\'。\"}, {\"field\": \"decisions\", \"index\": 1, \"detail\": \"decisions 第二条 owner_suggestion 错标为\'李悦\'，原文中灰度策略全程由陈磊汇报并承诺执行（含排班、监控、回滚），无李悦此人。\", \"issue_type\": \"UNSUPPORTED\", \"suggestion\": \"owner_suggestion 应修正为\'陈磊\'。\"}, {\"field\": \"decisions\", \"index\": 2, \"detail\": \"decisions 第三条 deadline_suggestion 为\'发布前一日下午6点前\'，正确；但 content 中仅写\'通稿及产品公告定稿时间\'，漏记原文关键共识\'通稿和产品公告均于发布当天上午10点同步发出\'，该时间点对市场协同至关重要，属必须记录的决策要素。\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"content 应补充：\'对外通稿与产品公告均于发布当天上午10:00同步发布\'。\"}, {\"field\": \"pending_items\", \"index\": -1, \"detail\": \"pending_items 仅列出2项，但原文明确三项行动项：①张涛本周五前完成报表导出异步化改造（\'张涛负责报表导出异步化改造，本周五前完成\'）；②陈磊明天下班前提交灰度值班排班表；③刘颖负责通稿定稿（已体现在decisions中，但 pending_items 未单列排班表交付动作）。其中第一项\'周五前完成\'是独立、强约束的待办，未出现在 pending_items 中。\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"应新增 pending_item：content: \'报表导出异步化改造完成并上线验证\'，owner_suggestion: \'张涛\'，deadline_suggestion: \'本周五下班前\'。\"}, {\"field\": \"pending_items\", \"index\": 0, \"detail\": \"pending_items 第一项 deadline_suggestion 为\'明天下班前\'，原文中陈磊说\'我明天下班前把排班表发到群里\'，但未明确\'明天\'对应具体日期（如发布前X日），属时间模糊，无法跨日执行。\", \"issue_type\": \"VAGUE\", \"suggestion\": \"deadline_suggestion 应写为绝对日期，如\'发布前两日18:00前\'（需根据会议召开日推算），或至少标注\'会议次日18:00前\'。\"}, {\"field\": \"risks\", \"index\": 0, \"detail\": \"risks 中 suggestion 写\'张涛须周三反馈中期进度；若未完成联调，则报表导出推至下个版本\'，但原文中明确决策为\'张涛，你这周三给我一个中期进度，如果到周三还没完成联调，我们就把报表导出推到下个版本\'，该句是会议达成的刚性决策，应放入 decisions 而非 risks；当前 risks 将其弱化为建议，且未体现\'推至下版本\'是确定动作而非可选项。\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"该条应从 risks 移入 decisions，作为第四条决策：basis: \'若周三未完成联调，则报表导出无法赶上V2.0发布\'；content: \'若张涛于本周三未完成联调，则报表导出功能正式延期至V2.1版本\'；owner_suggestion: \'张涛\'；deadline_suggestion: \'本周三\'。\"}, {\"field\": \"summary\", \"index\": -1, \"detail\": \"summary 中未提及\'发布当天上午10点同步发布通稿与产品公告\'这一明确时间点和协同动作，该信息在原文中由刘颖提出、全体确认，属会议核心结论之一，摘要必须涵盖。\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"summary 应补充：\'对外通稿与产品公告将于发布当天上午10:00同步发布\'。\"}], \"passed\": false}', 'SUCCEEDED', 37342, NULL, '2026-09-16 02:37:02', '2026-09-16 10:37:39');
INSERT INTO `agent_step` VALUES (15, 3, 4, 2, 'REFINE', '第2轮：按 5 条问题重写', '已按 5 条问题重写', '{\"risks\": [{\"level\": \"HIGH\", \"content\": \"模型服务延迟波动导致纪要生成与Agent运行等待时间延长，影响用户体验。\", \"suggestion\": \"发布首周每日查看运行观测中心的调用量、失败率、平均耗时和token使用量。\"}, {\"level\": \"MEDIUM\", \"content\": \"会议资料频繁更新导致知识索引长期处于‘需要重建’状态，影响检索时效性与一致性。\", \"suggestion\": \"建议资料整理完成后统一发起知识索引构建。\"}, {\"level\": \"HIGH\", \"content\": \"任务负责人分配不合理风险：Agent仅提供建议，最终由用户确认，存在人为误配可能；无技术强制校验机制。\", \"suggestion\": \"前端在任务创建页增加‘负责人负载提示’，展示建议人选当前待办任务数及平均处理时长，辅助用户决策。\"}, {\"level\": \"HIGH\", \"content\": \"删除用户时若关联历史业务记录（会议、任务、转写、纪要、问答、Agent运行、质量评价），系统将阻止删除操作，影响账号生命周期管理。\", \"suggestion\": \"管理员须先调整相关业务记录中的负责人、创建人或协作人关系，确保人员信息可追溯。\"}, {\"level\": \"HIGH\", \"content\": \"阻断任务未按时完成将触发发布时间调整风险\", \"suggestion\": \"按pending_items约定，由张晨与王工于8月31日17:00召开专项评审。\"}], \"topics\": [{\"title\": \"上一轮产品灰度发布的数据复盘\", \"summary\": \"复盘8月20日至26日灰度发布数据，覆盖10%-30%活跃用户，评估登录成功率、核心下单链路成功率、新功能访问与转化提升、用户反馈高频问题、权限控制验证及数据安全性。\"}, {\"title\": \"9月1日正式发布的功能范围和风险\", \"summary\": \"明确9月1日正式发布功能范围，包括会议创建与状态流转、资料管理、音视频转写、AI纪要、任务跟踪、知识库、React Agent分析、运行观测与质量评价；同步确认移动端附件下载问题须修复并写入发布说明。\"}, {\"title\": \"明确发布前后的任务负责人、协作人和完成期限\", \"summary\": \"确定发布前后各项任务的责任人、协作人与完成期限，涵盖移动端修复、回归测试、运营公告、客服知识库建设、首周数据复盘等五类关键事项。\"}], \"summary\": \"本次会议完成AI智能会议助手灰度发布复盘，确认核心功能稳定、权限合规、主流程可用；明确9月1日9:00正式发布，覆盖会议全生命周期与AI任务跟踪能力；识别并定义5项关键风险（含4项高风险），落实7项关键任务及责任人与截止时间；设定首周数据复盘框架与运营支持机制；约定阻断任务未完成时的专项评审机制。\", \"decisions\": [{\"basis\": \"灰度发布数据显示核心链路成功率高（登录99.8%，下单99.2%），无数据丢失、权限越界或重复提交问题；权限控制与预期一致；模型调用成功率97.9%-98.6%，失败可重试；主流程和边界场景已验证通过。\", \"content\": \"同意于9月1日9:00正式发布AI智能会议助手与任务跟踪系统，发布范围包括会议创建和状态流转、会议资料管理、音视频转写、AI纪要、任务跟踪、会议知识库、React Agent数据分析、运行观测和质量评价。\", \"owner_suggestion\": \"全体负责人\", \"deadline_suggestion\": \"2023-09-01T09:00:00\"}, {\"basis\": \"移动端附件下载进度未刷新问题影响发布当天支持成本，且已在灰度中被用户集中反馈；研发计划今日完成接口与前端验证。\", \"content\": \"移动端附件下载进度问题须在发布前修复，并在发布说明中写明处理结果。\", \"owner_suggestion\": \"王工（后端负责人）\", \"deadline_suggestion\": \"2023-08-30T18:00:00\"}, {\"basis\": \"测试团队已完成主流程及三类边界场景验证，但需补充两组验收数据以覆盖长音频与多角色说话人匹配场景。\", \"content\": \"发布前须完成两组补充验收：①至少30分钟真实会议录音，验证长音频切分、异步进度与长文本纪要合并；②含多个角色发言的会议内容，验证说话人标签与员工身份匹配效果。\", \"owner_suggestion\": \"陈琳（测试负责人）\", \"deadline_suggestion\": \"2023-08-31T12:00:00\"}, {\"basis\": \"运营需支撑上线后数据观察与用户引导，客服需快速定位问答来源以提升响应质量。\", \"content\": \"运营负责人赵敏牵头，协作人周宁，于9月1日9:00前完成发布公告与部门通知。\", \"owner_suggestion\": \"赵敏（运营负责人）\", \"deadline_suggestion\": \"2023-09-01T09:00:00\"}, {\"basis\": \"运营需支撑上线后数据观察与用户引导，客服需快速定位问答来源以提升响应质量。\", \"content\": \"客户支持负责人周宁牵头，协作人赵敏，于9月1日10:00前完成常见问题知识库建设。\", \"owner_suggestion\": \"周宁（客户支持负责人）\", \"deadline_suggestion\": \"2023-09-01T10:00:00\"}, {\"basis\": \"张晨提出首周复盘需结构化追踪五类核心数据，质量评价页面已支持综合评分采集。\", \"content\": \"产品负责人张晨负责发布决策复盘与首周数据汇总，重点分析会议创建数量与总时长、转写任务成功率与平均耗时、已确认纪要/任务草稿/正式任务数量、任务完成率与逾期率、RAG问答调用量/Agent运行次数/工具调用成功率/人工确认次数，并在质量评价页面导出《纪要与Agent结果三维度评分报表》（含准确性、完整性、可执行性单项分及综合分），于9月8日18:00前提交。\", \"owner_suggestion\": \"张晨（产品负责人）\", \"deadline_suggestion\": \"2023-09-08T18:00:00\"}, {\"basis\": \"知识索引构建期间资料变化时，由资料维护人完成整理后重新构建，该操作规则为会议明确达成的行动共识。\", \"content\": \"知识索引构建期间若发生资料更新，须由资料维护人完成全部整理后，统一发起重建流程，确保索引一致性。\", \"owner_suggestion\": \"资料维护人\", \"deadline_suggestion\": \"2023-09-01T09:00:00\"}, {\"basis\": \"发布首周每日查看运行观测和质量评价数据，发现任务逾期、模型调用失败率升高或员工反馈集中时，及时形成跟进报告，该动作性要求为会议明确共识。\", \"content\": \"发布首周每日17:00前，由王工牵头汇总运行观测中心与质量评价数据，形成《AI会议助手首周运行日报》，重点标注任务逾期率突增、模型失败率>2%、员工集中反馈TOP3问题，并同步至张晨、赵敏、周宁。\", \"owner_suggestion\": \"王工（后端负责人）\", \"deadline_suggestion\": \"2023-09-01T17:00:00\"}], \"viewpoints\": [{\"speaker\": \"张晨\", \"viewpoint\": \"灰度期间整体登录成功率为99.8%，核心下单链路成功率为99.2%；会议任务看板访问量提升24%，任务完成凭证上传率提升18%；用户集中反馈两个问题：①部分用户不知如何从会议纪要进入任务草稿；②移动端弱网下附件下载进度未及时刷新；已确认无数据丢失、权限越界或订单重复提交；四类账号权限控制符合预期；移动端附件下载体验问题需在正式发布前完成处理。\"}, {\"speaker\": \"王工\", \"viewpoint\": \"灰度期间后端接口无500错误；会议纪要模型调用成功率为98.6%（平均耗时7.8秒），Agent工具调用成功率为97.9%；两次失败源于外部模型服务短暂超时，系统已保存失败原因并支持用户重试；所有会议相关数据（转写、纪要、知识索引、Agent运行记录）均存于MySQL；知识索引更新时旧版本仍可检索，直至新版本切换完成；当前RE返回结构已包含引用会议名称、来源类型、时间点和原文片段。\"}, {\"speaker\": \"陈琳\", \"viewpoint\": \"已完成会议创建、参会人维护、音视频上传转写、说话人匹配、纪要修订、任务草稿确认、延期转交、RE问答、Agent人工确认及运行中断恢复等主流程验证；三类边界场景验证通过：①无权限访问返回明确提示；②仅草稿与已确认版本可导出；③已完成任务不可修改进度或发送提醒；需补充两组验收数据：①≥30分钟真实会议录音；②多角色发言会议用于验证说话人标签匹配效果；测试团队将于8月31日12:00前完成回归并提交凭证。\"}, {\"speaker\": \"赵敏\", \"viewpoint\": \"建议增加两项发布后观察指标：①员工从会议纪要创建正式任务的转化率；②任务逾期率；上线后一周内按部门统计会议数量、时长、任务完成率、逾期率及高频问题；逾期任务详情页展示提醒记录；每日16:00汇总高风险任务并同步至部门负责人与客服负责人；客服关注知识问答引用是否清晰（需含会议名称、来源类型、时间点、原文片段）。\"}, {\"speaker\": \"周宁\", \"viewpoint\": \"客服侧需在常见问题知识库中覆盖账号登录、会议权限、资料上传、格式转写失败、重试、纪要导出、任务负责人调整、知识索引状态、Agent人工确认等内容；对无法复现问题，需记录会议编号、任务编号或Agent运行编号以便研发追踪。\"}], \"pending_items\": [{\"content\": \"当移动端附件下载进度任务（负责人王工，截止8月30日18:00）或发布回归任务（负责人陈琳，截止8月31日12:00）任一未按时完成时，触发专项评审：由张晨与王工于8月31日17:00召开专项评审，决定是否调整发布时间。\", \"owner_suggestion\": \"张晨、王工\", \"deadline_suggestion\": \"2023-08-31T17:00:00\"}]}', 'SUCCEEDED', 57978, NULL, '2026-09-16 02:37:20', '2026-09-16 10:38:18');
INSERT INTO `agent_step` VALUES (16, 4, 2, 1, 'REFINE', '第1轮：按 9 条问题重写', '已按 9 条问题重写', '{\"risks\": [{\"level\": \"MEDIUM\", \"content\": \"报表导出异步化改造与灰度发布排期过近，若改造延期可能影响整体发布节奏或迫使功能延至下一版本。\", \"suggestion\": \"张涛须周三反馈中期进度；若未完成联调，则报表导出推至下个版本。\"}], \"topics\": [{\"title\": \"V2.0能否按期发布\", \"summary\": \"评估V2.0版本是否具备按期发布条件，重点聚焦17个计划需求的验收状态及剩余两个未闭环问题（报表导出、消息推送免打扰）的解决进展。\"}, {\"title\": \"灰度发布策略\", \"summary\": \"确定灰度发布的范围、节奏、技术实现方式（分流维度）、监控指标及回滚能力，确保平稳过渡。\"}, {\"title\": \"对外通稿与产品公告安排\", \"summary\": \"明确对外传播材料（通稿、产品公告）的内容边界、发布时间、协同节奏及定稿节点，确保信息与实际功能一致。\"}], \"summary\": \"本次会议围绕V2.0产品发布评审展开，确认核心功能验收基本完成，但报表导出存在性能瓶颈（40+秒超时、高失败率），决定发布时隐藏该功能入口；灰度采用分三阶段（10%→50%→100%）、用户ID取模分流、完备回滚方案；对外通稿须删减报表导出内容，并于发布前一日18:00前定稿；对外通稿与产品公告将于发布当天上午10:00同步发布；明确三项行动项及对应责任人与时间节点。\", \"decisions\": [{\"basis\": \"报表导出接口在压测中单用户导出三个月数据耗时40+秒，超网关30秒限制，500并发下失败率达12%，当前方案无法满足发布质量要求；异步改造需一周，无法在发布前完成。\", \"content\": \"V2.0按原计划时间发布，报表导出功能入口在发布时隐藏，待异步改造完成后单独上线。\", \"owner_suggestion\": \"张涛\", \"deadline_suggestion\": \"发布当日\"}, {\"basis\": \"灰度需兼顾稳定性与可观测性，且数据库改动均向后兼容，回滚成本低、速度快（5分钟）。\", \"content\": \"灰度分三阶段执行：首日10%流量、次日50%、第三日全量；按用户ID取模分流，确保用户一致性；回滚预案已就绪。\", \"owner_suggestion\": \"陈磊\", \"deadline_suggestion\": \"发布起连续三天\"}, {\"basis\": \"对外通稿需与实际发布功能严格一致，报表导出功能将被隐藏，故相关内容须删除；产品公告与通稿同步于发布当天上午10点发出，需预留审核时间。\", \"content\": \"对外通稿及产品公告定稿时间为发布前一日下午6点前，通稿中删除报表导出相关描述。对外通稿与产品公告均于发布当天上午10:00同步发布。\", \"owner_suggestion\": \"刘颖\", \"deadline_suggestion\": \"发布前一日下午6点前\"}, {\"basis\": \"若周三未完成联调，则报表导出无法赶上V2.0发布\", \"content\": \"若张涛于本周三未完成联调，则报表导出功能正式延期至V2.1版本\", \"owner_suggestion\": \"张涛\", \"deadline_suggestion\": \"本周三\"}], \"viewpoints\": [{\"speaker\": \"王敏\", \"viewpoint\": \"V2.0计划内17个需求已验收通过15个，剩余报表导出和消息推送免打扰设置两项；后者已修复并昨日回归通过\"}, {\"speaker\": \"张涛\", \"viewpoint\": \"报表导出压测暴露单用户导出三个月数据耗时40+秒、超网关30秒限制，500并发失败率12%；提出异步任务方案（导出返回任务号、后台生成、通知下载），需开发2天+联调1天+测试2天共5个工作日；用户体验优于缓存方案\"}, {\"speaker\": \"陈磊\", \"viewpoint\": \"系统容量充足（可支撑8万DAU，预估发布后5万）；灰度建议分三步（10%→50%→100%），按用户ID取模分流；监控核心指标为接口错误率、平均响应时间、核心链路转化率；回滚预案完备，数据库改动向后兼容，5分钟内可切回旧版；灰度期间需安排值班盯盘，排班表将于明天下班前发出；已配置三项核心指标告警，超阈值直接发至工作群\"}, {\"speaker\": \"刘颖\", \"viewpoint\": \"对外通稿初稿已完成，需根据最终功能清单调整；因报表导出将隐藏，通稿中对应段落需删除；建议发布当天上午10点同步发布通稿与产品公告。\"}], \"pending_items\": [{\"content\": \"灰度期间值班排班表制定与发布\", \"owner_suggestion\": \"陈磊\", \"deadline_suggestion\": \"会议次日18:00前\"}, {\"content\": \"报表导出异步化改造中期进度同步（周三反馈联调是否完成）\", \"owner_suggestion\": \"张涛\", \"deadline_suggestion\": \"本周三\"}, {\"content\": \"报表导出异步化改造完成并上线验证\", \"owner_suggestion\": \"张涛\", \"deadline_suggestion\": \"本周五下班前\"}]}', 'SUCCEEDED', 30078, NULL, '2026-09-16 02:37:39', '2026-09-16 10:38:09');
INSERT INTO `agent_step` VALUES (17, 4, 3, 2, 'REVIEW', '第2轮：审查是否可落实', '纪要整体结构完整，但存在多处关键遗漏和可落实性问题：summary未体现\'行动项有三个\'的明确数量及会议结束前复述结论的闭环动作；topics中\'V2.0能否按期发布\'议题未覆盖原文中\'消息推送免打扰已回归通过\'这一关键进展确认；viewpoints中张涛未记录\'缓存方案被否决\'这一决策依据；decisions中第四条决策\'若周三未完成联调则推至V2.1\'在原文中是风险提示+行动项（张涛周三给进度），而非正式决策；pending_items中\'报表导出异步化改造完成并上线验证\'的deadline写为\'本周五下班前\'，但原文明确是\'本周五前完成\'（含开发、联调、测试共5天），且未说明\'上线验证\'是否包含在内；risks中未记录原文明确提出的\'异步改造和灰度发布挨得太近\'这一具体风险表述。此外，所有pending_items和decisions中的owner_suggestion均使用\'suggestion\'后缀，不符合\'必须明确指定负责人\'的可落实要求。\n会议摘要整体｜原文里讨论过但纪要漏记：summary未提及会议结尾明确复述的三项结论（V2.0按期发布+灰度三步走+通稿定稿时间）及\'行动项有三个\'的量化表述，也未体现会议闭环特征（\'我复述一遍\'、\'今天就到这里散会\'） → 建议：补充：\'会议最终形成三项结论：V2.0按期发布（报表导出入口隐藏）、灰度分三阶段实施（10%→50%→100%）、对外通稿与产品公告于发布前一日18:00前定稿；明确三项行动项及责任人。\'\n议题第1条｜原文里讨论过但纪要漏记：topics中\'V2.0能否按期发布\'议题摘要未包含\'消息推送免打扰设置已修复并昨日回归通过\'这一关键验收进展，该信息直接影响\'能否按期发布\'的判断依据 → 建议：在该议题summary中补充：\'消息推送免打扰设置已修复并通过回归测试，仅报表导出存在性能瓶颈需延迟上线。\'\n发言观点第2条｜原文里讨论过但纪要漏记：viewpoints中张涛的发言未记录\'缓存方案被否决\'这一关键决策过程，原文明确\'缓存覆盖不全，用户选冷门区间还是慢\'，该信息是选择异步方案的核心依据 → 建议：在张涛viewpoint中补充：\'缓存方案因无法覆盖冷门时间区间被否决，异步方案为唯一可行解。\'\n决策第4条｜原文里讨论过但纪要漏记：decisions第四条将\'张涛周三给进度\'这一风险监控动作错误列为正式决策，原文中这是主持人提出的风险应对措施（\'这个风险记下来\'），且决策主体是会议共识而非张涛单方承诺 → 建议：删除该条decision，相关内容应归入risks模块，并明确标注为\'主持人提出的风险应对机制\'。\n待确认事项第3条｜转写原文里找不到依据：pending_items中\'报表导出异步化改造完成并上线验证\'的deadline写为\'本周五下班前\'，但原文明确\'开发两天，连调一天，测试两天，加起来一周\'，且主持人说\'本周五前完成\'，未限定\'下班前\'；\'上线验证\'在原文中无对应表述，属UNSUPPORTED添加 → 建议：修正为：\'报表导出异步化改造（含开发、联调、测试）于本周五前完成\'，删除\'上线验证\'。\n待确认事项第1条｜无法落成可执行任务：pending_items中所有条目owner_suggestion字段使用\'suggestion\'后缀，不符合\'必须明确指定负责人\'的可落实要求，原文中均为直接指派（\'张涛负责\'、\'陈磊明天下班前提交\'、\'刘颖负责通稿定稿\'） → 建议：将\'owner_suggestion\'统一改为\'owner\'，值为\'张涛\'、\'陈磊\'、\'刘颖\'。\n待确认事项第1条｜表述含糊：pending_items中\'灰度期间值班排班表制定与发布\'的deadline写为\'会议次日18:00前\'，但原文明确\'明天下班前\'，\'下班前\'是弹性时间点，\'18:00前\'属过度精确且无依据 → 建议：修正为\'明天下班前\'，与原文完全一致。\n风险与争议第1条｜原文里讨论过但纪要漏记：risks中未记录原文明确提出的\'异步改造和灰度发布挨得太近\'这一原话风险描述，仅泛化为\'排期过近\'，丢失关键语境 → 建议：在risks content中补充原话：\'异步改造和灰度发布挨得太近\'。', '{\"score\": 40, \"issues\": [{\"field\": \"summary\", \"index\": -1, \"detail\": \"summary未提及会议结尾明确复述的三项结论（V2.0按期发布+灰度三步走+通稿定稿时间）及\'行动项有三个\'的量化表述，也未体现会议闭环特征（\'我复述一遍\'、\'今天就到这里散会\'）\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"补充：\'会议最终形成三项结论：V2.0按期发布（报表导出入口隐藏）、灰度分三阶段实施（10%→50%→100%）、对外通稿与产品公告于发布前一日18:00前定稿；明确三项行动项及责任人。\'\"}, {\"field\": \"topics\", \"index\": 0, \"detail\": \"topics中\'V2.0能否按期发布\'议题摘要未包含\'消息推送免打扰设置已修复并昨日回归通过\'这一关键验收进展，该信息直接影响\'能否按期发布\'的判断依据\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"在该议题summary中补充：\'消息推送免打扰设置已修复并通过回归测试，仅报表导出存在性能瓶颈需延迟上线。\'\"}, {\"field\": \"viewpoints\", \"index\": 1, \"detail\": \"viewpoints中张涛的发言未记录\'缓存方案被否决\'这一关键决策过程，原文明确\'缓存覆盖不全，用户选冷门区间还是慢\'，该信息是选择异步方案的核心依据\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"在张涛viewpoint中补充：\'缓存方案因无法覆盖冷门时间区间被否决，异步方案为唯一可行解。\'\"}, {\"field\": \"decisions\", \"index\": 3, \"detail\": \"decisions第四条将\'张涛周三给进度\'这一风险监控动作错误列为正式决策，原文中这是主持人提出的风险应对措施（\'这个风险记下来\'），且决策主体是会议共识而非张涛单方承诺\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"删除该条decision，相关内容应归入risks模块，并明确标注为\'主持人提出的风险应对机制\'。\"}, {\"field\": \"pending_items\", \"index\": 2, \"detail\": \"pending_items中\'报表导出异步化改造完成并上线验证\'的deadline写为\'本周五下班前\'，但原文明确\'开发两天，连调一天，测试两天，加起来一周\'，且主持人说\'本周五前完成\'，未限定\'下班前\'；\'上线验证\'在原文中无对应表述，属UNSUPPORTED添加\", \"issue_type\": \"UNSUPPORTED\", \"suggestion\": \"修正为：\'报表导出异步化改造（含开发、联调、测试）于本周五前完成\'，删除\'上线验证\'。\"}, {\"field\": \"pending_items\", \"index\": 0, \"detail\": \"pending_items中所有条目owner_suggestion字段使用\'suggestion\'后缀，不符合\'必须明确指定负责人\'的可落实要求，原文中均为直接指派（\'张涛负责\'、\'陈磊明天下班前提交\'、\'刘颖负责通稿定稿\'）\", \"issue_type\": \"NOT_ACTIONABLE\", \"suggestion\": \"将\'owner_suggestion\'统一改为\'owner\'，值为\'张涛\'、\'陈磊\'、\'刘颖\'。\"}, {\"field\": \"pending_items\", \"index\": 0, \"detail\": \"pending_items中\'灰度期间值班排班表制定与发布\'的deadline写为\'会议次日18:00前\'，但原文明确\'明天下班前\'，\'下班前\'是弹性时间点，\'18:00前\'属过度精确且无依据\", \"issue_type\": \"VAGUE\", \"suggestion\": \"修正为\'明天下班前\'，与原文完全一致。\"}, {\"field\": \"risks\", \"index\": 0, \"detail\": \"risks中未记录原文明确提出的\'异步改造和灰度发布挨得太近\'这一原话风险描述，仅泛化为\'排期过近\'，丢失关键语境\", \"issue_type\": \"MISSING_ITEM\", \"suggestion\": \"在risks content中补充原话：\'异步改造和灰度发布挨得太近\'。\"}], \"passed\": false}', 'SUCCEEDED', 29485, NULL, '2026-09-16 02:38:09', '2026-09-16 10:38:39');
INSERT INTO `agent_step` VALUES (18, 3, 5, 2, 'FINAL', '汇总自检结论', '已按审查发现的 5 条问题重写纪要，得分 60，达到 2 轮上限后没有再复审，请人工判断是否采用修订稿。', NULL, 'SUCCEEDED', 0, NULL, '2026-09-16 02:38:18', '2026-09-16 10:38:18');
INSERT INTO `agent_step` VALUES (19, 4, 4, 2, 'REFINE', '第2轮：按 8 条问题重写', '已按 8 条问题重写', '{\"risks\": [{\"level\": \"MEDIUM\", \"content\": \"报表导出异步化改造与灰度发布排期过近，若改造延期可能影响整体发布节奏或迫使功能延至下一版本。异步改造和灰度发布挨得太近。\", \"suggestion\": \"张涛须周三反馈中期进度；若未完成联调，则报表导出推至下个版本。主持人提出的风险应对机制。\"}], \"topics\": [{\"title\": \"V2.0能否按期发布\", \"summary\": \"评估V2.0版本是否具备按期发布条件，重点聚焦17个计划需求的验收状态及剩余两个未闭环问题（报表导出、消息推送免打扰）的解决进展。消息推送免打扰设置已修复并通过回归测试，仅报表导出存在性能瓶颈需延迟上线。\"}, {\"title\": \"灰度发布策略\", \"summary\": \"确定灰度发布的范围、节奏、技术实现方式（分流维度）、监控指标及回滚能力，确保平稳过渡。\"}, {\"title\": \"对外通稿与产品公告安排\", \"summary\": \"明确对外传播材料（通稿、产品公告）的内容边界、发布时间、协同节奏及定稿节点，确保信息与实际功能一致。\"}], \"summary\": \"本次会议围绕V2.0产品发布评审展开，确认核心功能验收基本完成，但报表导出存在性能瓶颈（40+秒超时、高失败率），决定发布时隐藏该功能入口；灰度采用分三阶段（10%→50%→100%）、用户ID取模分流、完备回滚方案；对外通稿须删减报表导出内容，并于发布前一日18:00前定稿；对外通稿与产品公告将于发布当天上午10:00同步发布；会议最终形成三项结论：V2.0按期发布（报表导出入口隐藏）、灰度分三阶段实施（10%→50%→100%）、对外通稿与产品公告于发布前一日18:00前定稿；明确三项行动项及责任人。\", \"decisions\": [{\"basis\": \"报表导出接口在压测中单用户导出三个月数据耗时40+秒，超网关30秒限制，500并发下失败率达12%，当前方案无法满足发布质量要求；异步改造需一周，无法在发布前完成。\", \"content\": \"V2.0按原计划时间发布，报表导出功能入口在发布时隐藏，待异步改造完成后单独上线。\", \"owner_suggestion\": \"张涛\", \"deadline_suggestion\": \"发布当日\"}, {\"basis\": \"灰度需兼顾稳定性与可观测性，且数据库改动均向后兼容，回滚成本低、速度快（5分钟）。\", \"content\": \"灰度分三阶段执行：首日10%流量、次日50%、第三日全量；按用户ID取模分流，确保用户一致性；回滚预案已就绪。\", \"owner_suggestion\": \"陈磊\", \"deadline_suggestion\": \"发布起连续三天\"}, {\"basis\": \"对外通稿需与实际发布功能严格一致，报表导出功能将被隐藏，故相关内容须删除；产品公告与通稿同步于发布当天上午10点发出，需预留审核时间。\", \"content\": \"对外通稿及产品公告定稿时间为发布前一日下午6点前，通稿中删除报表导出相关描述。对外通稿与产品公告均于发布当天上午10:00同步发布。\", \"owner_suggestion\": \"刘颖\", \"deadline_suggestion\": \"发布前一日下午6点前\"}], \"viewpoints\": [{\"speaker\": \"王敏\", \"viewpoint\": \"V2.0计划内17个需求已验收通过15个，剩余报表导出和消息推送免打扰设置两项；后者已修复并昨日回归通过\"}, {\"speaker\": \"张涛\", \"viewpoint\": \"报表导出压测暴露单用户导出三个月数据耗时40+秒、超网关30秒限制，500并发失败率12%；提出异步任务方案（导出返回任务号、后台生成、通知下载），需开发2天+联调1天+测试2天共5个工作日；用户体验优于缓存方案；缓存方案因无法覆盖冷门时间区间被否决，异步方案为唯一可行解。\"}, {\"speaker\": \"陈磊\", \"viewpoint\": \"系统容量充足（可支撑8万DAU，预估发布后5万）；灰度建议分三步（10%→50%→100%），按用户ID取模分流；监控核心指标为接口错误率、平均响应时间、核心链路转化率；回滚预案完备，数据库改动向后兼容，5分钟内可切回旧版；灰度期间需安排值班盯盘，排班表将于明天下班前发出；已配置三项核心指标告警，超阈值直接发至工作群\"}, {\"speaker\": \"刘颖\", \"viewpoint\": \"对外通稿初稿已完成，需根据最终功能清单调整；因报表导出将隐藏，通稿中对应段落需删除；建议发布当天上午10点同步发布通稿与产品公告。\"}], \"pending_items\": [{\"content\": \"灰度期间值班排班表制定与发布\", \"owner_suggestion\": \"陈磊\", \"deadline_suggestion\": \"明天下班前\"}, {\"content\": \"报表导出异步化改造中期进度同步（周三反馈联调是否完成）\", \"owner_suggestion\": \"张涛\", \"deadline_suggestion\": \"本周三\"}, {\"content\": \"报表导出异步化改造（含开发、联调、测试）于本周五前完成\", \"owner_suggestion\": \"张涛\", \"deadline_suggestion\": \"本周五前\"}]}', 'SUCCEEDED', 31055, NULL, '2026-09-16 02:38:39', '2026-09-16 10:39:10');
INSERT INTO `agent_step` VALUES (20, 4, 5, 2, 'FINAL', '汇总自检结论', '已按审查发现的 8 条问题重写纪要，得分 40，达到 2 轮上限后没有再复审，请人工判断是否采用修订稿。', NULL, 'SUCCEEDED', 0, NULL, '2026-09-16 02:39:10', '2026-09-16 10:39:10');

-- ----------------------------
-- Table structure for ai_call_log
-- ----------------------------
DROP TABLE IF EXISTS `ai_call_log`;
CREATE TABLE `ai_call_log`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'AI调用日志ID',
  `request_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '单次模型请求唯一编号',
  `call_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '转写、纪要、纪要自检或说话人匹配的调用类型',
  `biz_id` int NOT NULL COMMENT '关联转写、纪要、索引、问答、Agent运行或发起用户ID',
  `model_config_id` int NOT NULL COMMENT '模型配置ID',
  `model_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '调用的模型名称',
  `request_size` bigint NOT NULL DEFAULT 0 COMMENT '本次请求内容字节数',
  `response_size` bigint NOT NULL DEFAULT 0 COMMENT '模型返回JSON字节数',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '调用状态：SUCCEEDED、FAILED',
  `elapsed_ms` bigint NOT NULL DEFAULT 0 COMMENT '调用耗时毫秒',
  `usage_json` json NULL COMMENT '模型返回的usage统计',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '调用失败原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '调用时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ai_call_request_id`(`request_id` ASC) USING BTREE,
  INDEX `idx_ai_call_type_time`(`call_type` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_ai_call_biz_id`(`biz_id` ASC) USING BTREE,
  INDEX `idx_ai_call_model_time_status`(`model_config_id` ASC, `create_time` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 30 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI模型调用日志表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_call_log
-- ----------------------------
