-- ----------------------------
-- Table structure for meeting_minutes
-- ----------------------------
DROP TABLE IF EXISTS `meeting_minutes`;
CREATE TABLE `meeting_minutes`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '会议纪要ID',
  `meeting_id` int NOT NULL COMMENT '会议ID',
  `source_task_id` int NOT NULL COMMENT '来源转写任务ID',
  `model_config_id` int NOT NULL COMMENT '纪要生成模型配置ID',
  `status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'GENERATING' COMMENT '状态：GENERATING、DRAFT、CONFIRMED、FAILED',
  `stage` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '等待生成' COMMENT '当前生成阶段',
  `progress` int NOT NULL DEFAULT 0 COMMENT '生成进度0至100',
  `summary` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '会议摘要',
  `topics_json` json NOT NULL COMMENT '议题总结数组',
  `viewpoints_json` json NOT NULL COMMENT '发言观点数组',
  `decisions_json` json NOT NULL COMMENT '会议决策数组',
  `pending_items_json` json NOT NULL COMMENT '待确认事项数组',
  `risks_json` json NOT NULL COMMENT '风险与争议点数组',
  `created_by` int NOT NULL COMMENT '生成发起人ID',
  `confirmed_by` int NULL DEFAULT NULL COMMENT '确认人ID',
  `confirmed_time` datetime NULL DEFAULT NULL COMMENT '确认时间',
  `error_message` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '生成失败原因',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_minutes_source_task`(`source_task_id` ASC) USING BTREE,
  INDEX `idx_minutes_meeting_status`(`meeting_id` ASC, `status` ASC) USING BTREE,
  INDEX `idx_minutes_source_task_id`(`source_task_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'AI会议纪要版本表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of meeting_minutes
-- ----------------------------
INSERT INTO `meeting_minutes` VALUES (3, 2, 6, 2, 'CONFIRMED', '纪要已生成', 100, '本次会议完成AI智能会议助手灰度发布复盘，确认核心功能稳定、权限合规、主流程可用；明确9月1日9:00正式发布，覆盖会议全生命周期与AI任务跟踪能力；识别并定义5项关键风险（含4项高风险），落实7项关键任务及责任人与截止时间；设定首周数据复盘框架与运营支持机制；约定阻断任务未完成时的专项评审机制。', '[{\"title\": \"上一轮产品灰度发布的数据复盘\", \"summary\": \"复盘8月20日至26日灰度发布数据，覆盖10%-30%活跃用户，评估登录成功率、核心下单链路成功率、新功能访问与转化提升、用户反馈高频问题、权限控制验证及数据安全性。\"}, {\"title\": \"9月1日正式发布的功能范围和风险\", \"summary\": \"明确9月1日正式发布功能范围，包括会议创建与状态流转、资料管理、音视频转写、AI纪要、任务跟踪、知识库、React Agent分析、运行观测与质量评价；同步确认移动端附件下载问题须修复并写入发布说明。\"}, {\"title\": \"明确发布前后的任务负责人、协作人和完成期限\", \"summary\": \"确定发布前后各项任务的责任人、协作人与完成期限，涵盖移动端修复、回归测试、运营公告、客服知识库建设、首周数据复盘等五类关键事项。\"}]', '[{\"speaker\": \"张晨\", \"viewpoint\": \"灰度期间整体登录成功率为99.8%，核心下单链路成功率为99.2%；会议任务看板访问量提升24%，任务完成凭证上传率提升18%；用户集中反馈两个问题：①部分用户不知如何从会议纪要进入任务草稿；②移动端弱网下附件下载进度未及时刷新；已确认无数据丢失、权限越界或订单重复提交；四类账号权限控制符合预期；移动端附件下载体验问题需在正式发布前完成处理。\"}, {\"speaker\": \"王工\", \"viewpoint\": \"灰度期间后端接口无500错误；会议纪要模型调用成功率为98.6%（平均耗时7.8秒），Agent工具调用成功率为97.9%；两次失败源于外部模型服务短暂超时，系统已保存失败原因并支持用户重试；所有会议相关数据（转写、纪要、知识索引、Agent运行记录）均存于MySQL；知识索引更新时旧版本仍可检索，直至新版本切换完成；当前RE返回结构已包含引用会议名称、来源类型、时间点和原文片段。\"}, {\"speaker\": \"陈琳\", \"viewpoint\": \"已完成会议创建、参会人维护、音视频上传转写、说话人匹配、纪要修订、任务草稿确认、延期转交、RE问答、Agent人工确认及运行中断恢复等主流程验证；三类边界场景验证通过：①无权限访问返回明确提示；②仅草稿与已确认版本可导出；③已完成任务不可修改进度或发送提醒；需补充两组验收数据：①≥30分钟真实会议录音；②多角色发言会议用于验证说话人标签匹配效果；测试团队将于8月31日12:00前完成回归并提交凭证。\"}, {\"speaker\": \"赵敏\", \"viewpoint\": \"建议增加两项发布后观察指标：①员工从会议纪要创建正式任务的转化率；②任务逾期率；上线后一周内按部门统计会议数量、时长、任务完成率、逾期率及高频问题；逾期任务详情页展示提醒记录；每日16:00汇总高风险任务并同步至部门负责人与客服负责人；客服关注知识问答引用是否清晰（需含会议名称、来源类型、时间点、原文片段）。\"}, {\"speaker\": \"周宁\", \"viewpoint\": \"客服侧需在常见问题知识库中覆盖账号登录、会议权限、资料上传、格式转写失败、重试、纪要导出、任务负责人调整、知识索引状态、Agent人工确认等内容；对无法复现问题，需记录会议编号、任务编号或Agent运行编号以便研发追踪。\"}]', '[{\"basis\": \"灰度发布数据显示核心链路成功率高（登录99.8%，下单99.2%），无数据丢失、权限越界或重复提交问题；权限控制与预期一致；模型调用成功率97.9%-98.6%，失败可重试；主流程和边界场景已验证通过。\", \"content\": \"同意于9月1日9:00正式发布AI智能会议助手与任务跟踪系统，发布范围包括会议创建和状态流转、会议资料管理、音视频转写、AI纪要、任务跟踪、会议知识库、React Agent数据分析、运行观测和质量评价。\", \"owner_suggestion\": \"全体负责人\", \"deadline_suggestion\": \"2023-09-01T09:00:00\"}, {\"basis\": \"移动端附件下载进度未刷新问题影响发布当天支持成本，且已在灰度中被用户集中反馈；研发计划今日完成接口与前端验证。\", \"content\": \"移动端附件下载进度问题须在发布前修复，并在发布说明中写明处理结果。\", \"owner_suggestion\": \"王工（后端负责人）\", \"deadline_suggestion\": \"2023-08-30T18:00:00\"}, {\"basis\": \"测试团队已完成主流程及三类边界场景验证，但需补充两组验收数据以覆盖长音频与多角色说话人匹配场景。\", \"content\": \"发布前须完成两组补充验收：①至少30分钟真实会议录音，验证长音频切分、异步进度与长文本纪要合并；②含多个角色发言的会议内容，验证说话人标签与员工身份匹配效果。\", \"owner_suggestion\": \"陈琳（测试负责人）\", \"deadline_suggestion\": \"2023-08-31T12:00:00\"}, {\"basis\": \"运营需支撑上线后数据观察与用户引导，客服需快速定位问答来源以提升响应质量。\", \"content\": \"运营负责人赵敏牵头，协作人周宁，于9月1日9:00前完成发布公告与部门通知。\", \"owner_suggestion\": \"赵敏（运营负责人）\", \"deadline_suggestion\": \"2023-09-01T09:00:00\"}, {\"basis\": \"运营需支撑上线后数据观察与用户引导，客服需快速定位问答来源以提升响应质量。\", \"content\": \"客户支持负责人周宁牵头，协作人赵敏，于9月1日10:00前完成常见问题知识库建设。\", \"owner_suggestion\": \"周宁（客户支持负责人）\", \"deadline_suggestion\": \"2023-09-01T10:00:00\"}, {\"basis\": \"张晨提出首周复盘需结构化追踪五类核心数据，质量评价页面已支持综合评分采集。\", \"content\": \"产品负责人张晨负责发布决策复盘与首周数据汇总，重点分析会议创建数量与总时长、转写任务成功率与平均耗时、已确认纪要/任务草稿/正式任务数量、任务完成率与逾期率、RAG问答调用量/Agent运行次数/工具调用成功率/人工确认次数，并在质量评价页面导出《纪要与Agent结果三维度评分报表》（含准确性、完整性、可执行性单项分及综合分），于9月8日18:00前提交。\", \"owner_suggestion\": \"张晨（产品负责人）\", \"deadline_suggestion\": \"2023-09-08T18:00:00\"}, {\"basis\": \"知识索引构建期间资料变化时，由资料维护人完成整理后重新构建，该操作规则为会议明确达成的行动共识。\", \"content\": \"知识索引构建期间若发生资料更新，须由资料维护人完成全部整理后，统一发起重建流程，确保索引一致性。\", \"owner_suggestion\": \"资料维护人\", \"deadline_suggestion\": \"2023-09-01T09:00:00\"}, {\"basis\": \"发布首周每日查看运行观测和质量评价数据，发现任务逾期、模型调用失败率升高或员工反馈集中时，及时形成跟进报告，该动作性要求为会议明确共识。\", \"content\": \"发布首周每日17:00前，由王工牵头汇总运行观测中心与质量评价数据，形成《AI会议助手首周运行日报》，重点标注任务逾期率突增、模型失败率>2%、员工集中反馈TOP3问题，并同步至张晨、赵敏、周宁。\", \"owner_suggestion\": \"王工（后端负责人）\", \"deadline_suggestion\": \"2023-09-01T17:00:00\"}]', '[{\"content\": \"当移动端附件下载进度任务（负责人王工，截止8月30日18:00）或发布回归任务（负责人陈琳，截止8月31日12:00）任一未按时完成时，触发专项评审：由张晨与王工于8月31日17:00召开专项评审，决定是否调整发布时间。\", \"owner_suggestion\": \"张晨、王工\", \"deadline_suggestion\": \"2023-08-31T17:00:00\"}]', '[{\"level\": \"HIGH\", \"content\": \"模型服务延迟波动导致纪要生成与Agent运行等待时间延长，影响用户体验。\", \"suggestion\": \"发布首周每日查看运行观测中心的调用量、失败率、平均耗时和token使用量。\"}, {\"level\": \"MEDIUM\", \"content\": \"会议资料频繁更新导致知识索引长期处于‘需要重建’状态，影响检索时效性与一致性。\", \"suggestion\": \"建议资料整理完成后统一发起知识索引构建。\"}, {\"level\": \"HIGH\", \"content\": \"任务负责人分配不合理风险：Agent仅提供建议，最终由用户确认，存在人为误配可能；无技术强制校验机制。\", \"suggestion\": \"前端在任务创建页增加‘负责人负载提示’，展示建议人选当前待办任务数及平均处理时长，辅助用户决策。\"}, {\"level\": \"HIGH\", \"content\": \"删除用户时若关联历史业务记录（会议、任务、转写、纪要、问答、Agent运行、质量评价），系统将阻止删除操作，影响账号生命周期管理。\", \"suggestion\": \"管理员须先调整相关业务记录中的负责人、创建人或协作人关系，确保人员信息可追溯。\"}, {\"level\": \"HIGH\", \"content\": \"阻断任务未按时完成将触发发布时间调整风险\", \"suggestion\": \"按pending_items约定，由张晨与王工于8月31日17:00召开专项评审。\"}]', 1, 1, '2026-09-16 10:40:52', NULL, '2026-09-16 02:31:51', '2026-09-16 10:40:51');
INSERT INTO `meeting_minutes` VALUES (4, 2, 7, 2, 'DRAFT', '纪要已生成', 100, '本次会议围绕V2.0产品发布评审展开，确认核心功能验收基本完成，但报表导出存在性能瓶颈（40+秒超时、高失败率），决定发布时隐藏该功能入口；灰度采用分三阶段（10%→50%→100%）、用户ID取模分流、完备回滚方案；对外通稿须删减报表导出内容，并于发布前一日18:00前定稿；对外通稿与产品公告将于发布当天上午10:00同步发布；会议最终形成三项结论：V2.0按期发布（报表导出入口隐藏）、灰度分三阶段实施（10%→50%→100%）、对外通稿与产品公告于发布前一日18:00前定稿；明确三项行动项及责任人。', '[{\"title\": \"V2.0能否按期发布\", \"summary\": \"评估V2.0版本是否具备按期发布条件，重点聚焦17个计划需求的验收状态及剩余两个未闭环问题（报表导出、消息推送免打扰）的解决进展。消息推送免打扰设置已修复并通过回归测试，仅报表导出存在性能瓶颈需延迟上线。\"}, {\"title\": \"灰度发布策略\", \"summary\": \"确定灰度发布的范围、节奏、技术实现方式（分流维度）、监控指标及回滚能力，确保平稳过渡。\"}, {\"title\": \"对外通稿与产品公告安排\", \"summary\": \"明确对外传播材料（通稿、产品公告）的内容边界、发布时间、协同节奏及定稿节点，确保信息与实际功能一致。\"}]', '[{\"speaker\": \"王敏\", \"viewpoint\": \"V2.0计划内17个需求已验收通过15个，剩余报表导出和消息推送免打扰设置两项；后者已修复并昨日回归通过\"}, {\"speaker\": \"张涛\", \"viewpoint\": \"报表导出压测暴露单用户导出三个月数据耗时40+秒、超网关30秒限制，500并发失败率12%；提出异步任务方案（导出返回任务号、后台生成、通知下载），需开发2天+联调1天+测试2天共5个工作日；用户体验优于缓存方案；缓存方案因无法覆盖冷门时间区间被否决，异步方案为唯一可行解。\"}, {\"speaker\": \"陈磊\", \"viewpoint\": \"系统容量充足（可支撑8万DAU，预估发布后5万）；灰度建议分三步（10%→50%→100%），按用户ID取模分流；监控核心指标为接口错误率、平均响应时间、核心链路转化率；回滚预案完备，数据库改动向后兼容，5分钟内可切回旧版；灰度期间需安排值班盯盘，排班表将于明天下班前发出；已配置三项核心指标告警，超阈值直接发至工作群\"}, {\"speaker\": \"刘颖\", \"viewpoint\": \"对外通稿初稿已完成，需根据最终功能清单调整；因报表导出将隐藏，通稿中对应段落需删除；建议发布当天上午10点同步发布通稿与产品公告。\"}]', '[{\"basis\": \"报表导出接口在压测中单用户导出三个月数据耗时40+秒，超网关30秒限制，500并发下失败率达12%，当前方案无法满足发布质量要求；异步改造需一周，无法在发布前完成。\", \"content\": \"V2.0按原计划时间发布，报表导出功能入口在发布时隐藏，待异步改造完成后单独上线。\", \"owner_suggestion\": \"张涛\", \"deadline_suggestion\": \"发布当日\"}, {\"basis\": \"灰度需兼顾稳定性与可观测性，且数据库改动均向后兼容，回滚成本低、速度快（5分钟）。\", \"content\": \"灰度分三阶段执行：首日10%流量、次日50%、第三日全量；按用户ID取模分流，确保用户一致性；回滚预案已就绪。\", \"owner_suggestion\": \"陈磊\", \"deadline_suggestion\": \"发布起连续三天\"}, {\"basis\": \"对外通稿需与实际发布功能严格一致，报表导出功能将被隐藏，故相关内容须删除；产品公告与通稿同步于发布当天上午10点发出，需预留审核时间。\", \"content\": \"对外通稿及产品公告定稿时间为发布前一日下午6点前，通稿中删除报表导出相关描述。对外通稿与产品公告均于发布当天上午10:00同步发布。\", \"owner_suggestion\": \"刘颖\", \"deadline_suggestion\": \"发布前一日下午6点前\"}]', '[{\"content\": \"灰度期间值班排班表制定与发布\", \"owner_suggestion\": \"陈磊\", \"deadline_suggestion\": \"明天下班前\"}, {\"content\": \"报表导出异步化改造中期进度同步（周三反馈联调是否完成）\", \"owner_suggestion\": \"张涛\", \"deadline_suggestion\": \"本周三\"}, {\"content\": \"报表导出异步化改造（含开发、联调、测试）于本周五前完成\", \"owner_suggestion\": \"张涛\", \"deadline_suggestion\": \"本周五前\"}]', '[{\"level\": \"MEDIUM\", \"content\": \"报表导出异步化改造与灰度发布排期过近，若改造延期可能影响整体发布节奏或迫使功能延至下一版本。异步改造和灰度发布挨得太近。\", \"suggestion\": \"张涛须周三反馈中期进度；若未完成联调，则报表导出推至下个版本。主持人提出的风险应对机制。\"}]', 1, NULL, NULL, NULL, '2026-09-16 02:33:55', '2026-09-16 02:40:23');

-- ----------------------------
-- Table structure for meeting_participant
-- ----------------------------
DROP TABLE IF EXISTS `meeting_participant`;
CREATE TABLE `meeting_participant`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '参会记录ID',
  `meeting_id` int NOT NULL COMMENT '会议ID',
  `user_id` int NOT NULL COMMENT '参会员工用户ID',
  `participant_role` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PARTICIPANT' COMMENT '会议角色：CREATOR创建人、HOST主持人、PARTICIPANT参会人',
  `response_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING' COMMENT '参会状态：PENDING待确认、ACCEPTED参加、DECLINED不参加',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_meeting_participant`(`meeting_id` ASC, `user_id` ASC) USING BTREE,
  INDEX `idx_meeting_participant_user_id`(`user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '会议参会人员表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of meeting_participant
-- ----------------------------
INSERT INTO `meeting_participant` VALUES (3, 2, 1, 'HOST', 'ACCEPTED', '2026-09-10 02:37:02');
INSERT INTO `meeting_participant` VALUES (4, 2, 2, 'PARTICIPANT', 'PENDING', '2026-09-10 02:37:02');
INSERT INTO `meeting_participant` VALUES (5, 2, 3, 'PARTICIPANT', 'PENDING', '2026-09-10 02:37:02');

-- ----------------------------
-- Table structure for prompt_template
-- ----------------------------
DROP TABLE IF EXISTS `prompt_template`;
CREATE TABLE `prompt_template`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Prompt模板ID',
  `code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板唯一编码',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模板名称',
  `scene_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'MEETING_MINUTES' COMMENT '使用场景',
  `system_prompt` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '系统指令',
  `user_prompt` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '包含变量占位符的用户模板',
  `enabled` tinyint(1) NOT NULL DEFAULT 1 COMMENT '是否启用',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_prompt_code`(`code` ASC) USING BTREE,
  INDEX `idx_prompt_scene_enabled`(`scene_type` ASC, `enabled` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 15 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'Prompt模板表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of prompt_template
-- ----------------------------
INSERT INTO `prompt_template` VALUES (5, 'MEETING_MINUTES', '会议纪要生成', 'MEETING_MINUTES', '你是企业会议纪要信息抽取员。只根据输入的整场会议转写记录事实，区分已确定的决议、明确承诺执行的行动、会议明确留下的未决事项、泛泛建议、可选方案和假设性讨论。不得把讨论或建议提升为已决事项或任务，不得把推测写成会议已确定的负责人或期限。', '会议主题：{meeting_title}\n整场会议转写：\n{transcript}\n请生成完整、去重的结构化会议纪要（摘要、议题、发言观点、决策、待确认事项、风险与争议点）。只有原文明示已确定的决议或明确承诺执行的行动才放入 decisions；会议明确留下待讨论、待确认或需跟进的未决事项（含待决建议）放入 pending_items，保留其未承诺状态；未留下后续处理安排的泛泛建议、可选方案和假设归入 topics 或 viewpoints，不强行转成任务。risks 中的风险与争议事实须有原文依据；risks[].suggestion 可提出模型应对建议，但须明确标为模型建议而非会议决定。原文未明确负责人或期限时如实填“未提及”，不要留空、不要猜。', 1, '2026-10-06 00:00:00', '2026-10-06 00:00:00');
INSERT INTO `prompt_template` VALUES (7, 'MINUTES_REVIEW', '纪要自检审查', 'AGENT', '你是企业会议纪要事实审查员。转写原文是会议事实的唯一依据，当前纪要和已有审核意见都可能有误。严格区分已确定的决议、明确承诺执行的行动、会议明确留下的未决事项、泛泛建议、可选方案和假设性讨论。只提出能由原文核验且值得修订的问题，不得把建议、假设或一般讨论推断为已决事项或任务。', '会议主题：{meeting_title}\n\n转写原文：\n{transcript}\n\n当前纪要：\n{minutes_json}\n\n请核对 summary、topics、viewpoints、decisions、pending_items、risks 六部分，并遵守以下规则：\n1. 只有原文明示已确定的决议或明确承诺执行的行动才能写入 decisions；会议明确留下待讨论、待确认或需跟进的未决事项（含待决建议）写入 pending_items，保留其未承诺状态。未留下后续处理安排的泛泛建议、可选方案、假设和一般讨论可按原文记入 topics 或 viewpoints，不要强行转成决策或待办。risks 中的风险与争议事实须有原文依据；risks[].suggestion 可以是明确标为模型建议的应对建议，不得写成会议已决措施。\n2. 只对原文确有的重要遗漏使用 MISSING_ITEM，对无依据、确定性被夸大或把可选方案写成已决的内容使用 UNSUPPORTED。detail 应说明可核验的原文依据与纪要差异；整块缺失时 index 填 -1。提出修改建议前先核对原文。\n3. 仅当原文明示负责人或期限而纪要漏记、错记时，才使用 MISSING_OWNER 或 MISSING_DEADLINE。原文未说明时，写“待确认”或“未明确”是可接受的，不要求猜测或补造。owner_suggestion、deadline_suggestion 可以保留清楚标识为模型建议的内容，但不得当作会议已确定的人选或期限。VAGUE、NOT_ACTIONABLE 仅用于原文已明确要执行却表述不足的事项，不要求每个讨论点都成为任务。\n4. 无有据可查的问题时，passed=true 且 issues=[]；否则 passed=false，并只列出可由原文核验的问题。', 1, '2026-09-11 02:33:26', '2026-09-14 16:30:13');
INSERT INTO `prompt_template` VALUES (8, 'MINUTES_REFINE', '纪要自检修订', 'AGENT', '你是企业会议纪要事实修订员。转写原文是唯一会议事实依据；当前纪要和审核意见都不是独立证据，审核意见中的修改建议不是事实或会议决定。每项修改须回查原文，区分已决、明确承诺执行、会议明确留下的未决事项、泛泛建议与可选方案。原文没有给出或证据不足的细节保持不确定，不得编造决策、任务、负责人或期限。', '会议主题：{meeting_title}\n\n转写原文：\n{transcript}\n\n当前纪要：\n{minutes_json}\n\n审核意见：\n{issues}\n\n逐条核对审核意见与转写原文后输出修订后的完整纪要。只修正原文支持的遗漏、错记或确定性夸大；无依据的审核建议应忽略，原文支持且未被指出问题的内容保持原样。只有明确决议或承诺执行的行动写入 decisions；会议明确留下待讨论、待确认或需跟进的未决事项（含待决建议）写入 pending_items，并保留未承诺状态；未留下后续处理安排的泛泛建议、可选方案、假设和一般讨论按原文记入 topics 或 viewpoints，不转成已决事项或任务。risks 中的风险与争议事实须有原文依据；risks[].suggestion 可提出模型应对建议，但须明确标为模型建议而非会议决定。原文未明确负责人或期限时使用“待确认”或“未明确”；如填写 owner_suggestion、deadline_suggestion 中的推测，必须明确写成模型建议而非会议决定。', 1, '2026-09-11 02:33:26', '2026-09-11 02:33:26');
INSERT INTO `prompt_template` VALUES (9, 'SPEAKER_MATCH', '说话人建议匹配', 'TRANSCRIPTION', '你是会议转写分析助手。你要根据发言内容推断每个说话人标签对应的是哪位参会人员，只能从给定的参会人员名单里选，拿不准就不要选。', '会议主题：{meeting_title}\n\n参会人员名单：\n{participants}\n\n带说话人标签的转写片段：\n{transcript}\n\n请为每个说话人标签给出最可能的参会人员、判断依据和把握程度。点名句是最有力的依据，例如某人说“请王敏说一下”，紧接着开口的那个标签多半就是王敏。没有把握时把 user_id 置为 0。', 1, '2026-09-11 02:33:26', '2026-09-11 02:33:26');

-- ----------------------------
-- Table structure for transcript_segment
-- ----------------------------
DROP TABLE IF EXISTS `transcript_segment`;
CREATE TABLE `transcript_segment`  (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '转写片段ID',
  `task_id` int NOT NULL COMMENT '转写任务ID',
  `meeting_id` int NOT NULL COMMENT '会议ID',
  `segment_no` int NOT NULL COMMENT '时间轴顺序号',
  `start_ms` bigint NOT NULL DEFAULT 0 COMMENT '片段开始毫秒',
  `end_ms` bigint NOT NULL DEFAULT 0 COMMENT '片段结束毫秒',
  `speaker_label` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '模型识别的说话人标签',
  `speaker_user_id` int NULL DEFAULT NULL COMMENT '人工匹配的参会用户ID',
  `original_text` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '模型原始转写文本',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '页面当前使用的可修订文本',
  `revised_by` int NULL DEFAULT NULL COMMENT '最后修订人用户ID',
  `revised_time` datetime NULL DEFAULT NULL COMMENT '最后修订时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_transcript_task_segment`(`task_id` ASC, `segment_no` ASC) USING BTREE,
  INDEX `idx_transcript_meeting_time`(`meeting_id` ASC, `start_ms` ASC) USING BTREE,
  INDEX `idx_transcript_speaker_user_id`(`speaker_user_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 436 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '带时间轴和说话人的转写片段表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of transcript_segment
-- ----------------------------
INSERT INTO `transcript_segment` VALUES (308, 6, 2, 1, 0, 8676, '01-0', 2, '各位同事上午好，现在开始产品上线复盘与下阶段发布准备会议。', '各位同事上午好，现在开始产品上线复盘与下阶段发布准备会议。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (309, 6, 2, 2, 8676, 12210, '01-0', 2, '我是本次会议主持人李月。', '我是本次会议主持人李月。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (310, 6, 2, 3, 12210, 18958, '01-0', 2, '今天会议预计持续45分钟，主要讨论三个议题。', '今天会议预计持续45分钟，主要讨论三个议题。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (311, 6, 2, 4, 18958, 24100, '01-0', 2, '第一，上一轮产品灰度发布的数据复盘。', '第一，上一轮产品灰度发布的数据复盘。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (312, 6, 2, 5, 24100, 29770, '01-0', 2, '第二，9月1日正式发布的功能范围和风险。', '第二，9月1日正式发布的功能范围和风险。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (313, 6, 2, 6, 29770, 36700, '01-0', 2, '第三，明确发布前后的任务负责人、协作人和完成期限。', '第三，明确发布前后的任务负责人、协作人和完成期限。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (314, 6, 2, 7, 36700, 46780, '01-0', 2, '请大家围绕事实数据和可执行动作发言，会议结束后会形成纪要和任务清单。', '请大家围绕事实数据和可执行动作发言，会议结束后会形成纪要和任务清单。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (315, 6, 2, 8, 46780, 51876, '01-0', 2, '先请产品负责人张晨介绍灰度发布情况。', '先请产品负责人张晨介绍灰度发布情况。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (316, 6, 2, 9, 51876, 74060, '01-0', 2, '张晨本次灰度从8月20日开始覆盖10%的活跃用户，到8月26日扩大到30%，整体登录成功率为99.8%，核心下单链路成功率为99.2%。', '张晨本次灰度从8月20日开始覆盖10%的活跃用户，到8月26日扩大到30%，整体登录成功率为99.8%，核心下单链路成功率为99.2%。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (317, 6, 2, 10, 74060, 86542, '01-0', 2, '新版本的会议任务看板访问量比旧入口提升了24%，任务完成凭证上传率提升了18%。', '新版本的会议任务看板访问量比旧入口提升了24%，任务完成凭证上传率提升了18%。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (318, 6, 2, 11, 86542, 96703, '01-0', 2, '用户反馈最集中的问题有两个，第一部分用户不知道如何从会议纪要进入任务草稿。', '用户反馈最集中的问题有两个，第一部分用户不知道如何从会议纪要进入任务草稿。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (319, 6, 2, 12, 96703, 103380, '01-0', 2, '第二，移动端在网络较弱时，附件下载进度没有及时刷新。', '第二，移动端在网络较弱时，附件下载进度没有及时刷新。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (320, 6, 2, 13, 103380, 115977, '01-0', 2, '张晨继续说明，从买点和客服工单看，目前没有发现数据丢失、权限越界或订单重复提交的问题。', '张晨继续说明，从买点和客服工单看，目前没有发现数据丢失、权限越界或订单重复提交的问题。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (321, 6, 2, 14, 115977, 125667, '01-0', 2, '我们已经抽样检查了管理员、会议创建人、主持人、普通参会人员四类账号。', '我们已经抽样检查了管理员、会议创建人、主持人、普通参会人员四类账号。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (322, 6, 2, 15, 125667, 144796, '01-0', 2, '管理员可以查看企业会议数据，员工只可以看到自己创建、主持或参与的会议任务，负责人、创建人和协作人可以查看相关任务权限范围与预期一致。', '管理员可以查看企业会议数据，员工只可以看到自己创建、主持或参与的会议任务，负责人、创建人和协作人可以查看相关任务权限范围与预期一致。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (323, 6, 2, 16, 144796, 156480, '01-0', 2, '不过移动端附件下载的体验问题会影响发布当天的支持成本，需要在正式发布前完成处理。', '不过移动端附件下载的体验问题会影响发布当天的支持成本，需要在正式发布前完成处理。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (324, 6, 2, 17, 156480, 170072, '01-0', 2, '主持人李月请后端负责人王工补充服务和数据情况，王工，后端接口在灰度期间没有出现500错误。', '主持人李月请后端负责人王工补充服务和数据情况，王工，后端接口在灰度期间没有出现500错误。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (325, 6, 2, 18, 170072, 193681, '01-0', 2, 'Ar纪要转写re问答和agent运行的调用日志都已经进入观测中心，最近七天的会议纪要模型调用成功率为98.6%，平均耗时为7.8秒，agent工具调用成功率为97.9%。', 'Ar纪要转写re问答和agent运行的调用日志都已经进入观测中心，最近七天的会议纪要模型调用成功率为98.6%，平均耗时为7.8秒，agent工具调用成功率为97.9%。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (326, 6, 2, 19, 193681, 206300, '01-0', 2, '两次失败都来自外部模型服务短暂超时，系统已保存失败原因和耗时，用户可以从失败状态发起重试。', '两次失败都来自外部模型服务短暂超时，系统已保存失败原因和耗时，用户可以从失败状态发起重试。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (327, 6, 2, 20, 206300, 224814, '01-0', 2, '王工继续数据库方面，会议转写、纪要任务、知识索引和agent运行记录都保存在my sql知识库，切片也保存在my sql的J向梁字段中。', '王工继续数据库方面，会议转写、纪要任务、知识索引和agent运行记录都保存在my sql知识库，切片也保存在my sql的J向梁字段中。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (328, 6, 2, 21, 224814, 249975, '01-0', 2, '我们检查了长会议的转写和纪要生成流程，音频会按时长切分，转写完成后生成带时间轴的片段，既要会按文本长度分段总结，再合并为摘要议题发言观点、决策该确认事项和风险。', '我们检查了长会议的转写和纪要生成流程，音频会按时长切分，转写完成后生成带时间轴的片段，既要会按文本长度分段总结，再合并为摘要议题发言观点、决策该确认事项和风险。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (329, 6, 2, 22, 249975, 261995, '01-0', 2, '对于资料更新，知识索引会标记为需要重建，旧版本仍保持可检索，直到新版本完成切换。', '对于资料更新，知识索引会标记为需要重建，旧版本仍保持可检索，直到新版本完成切换。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (330, 6, 2, 23, 261995, 269086, '01-0', 2, '主持人李月，请测试负责人陈琳介绍质量验证情况。', '主持人李月，请测试负责人陈琳介绍质量验证情况。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (331, 6, 2, 24, 269086, 293464, '01-0', 2, '陈琳目前已完成会议创建，参会人员维护录音和视频资料上传转写，发起说话人匹配、纪要修订、确认任务草稿、确认任务延期转交re问答agent人工确认和运行中断恢复的主流程验证。', '陈琳目前已完成会议创建，参会人员维护录音和视频资料上传转写，发起说话人匹配、纪要修订、确认任务草稿、确认任务延期转交re问答agent人工确认和运行中断恢复的主流程验证。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (332, 6, 2, 25, 293464, 308380, '01-0', 2, '我们重点关注了三类边界场景，第一，会议参与人访问不属于自己的会议资料时，接口会返回，没有会议访问权限。', '我们重点关注了三类边界场景，第一，会议参与人访问不属于自己的会议资料时，接口会返回，没有会议访问权限。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (333, 6, 2, 26, 308380, 320278, '01-0', 2, '第二，既要处于生成中或失败状态时不能导出，只有草稿和已确认版本可以导出word或pdf。', '第二，既要处于生成中或失败状态时不能导出，只有草稿和已确认版本可以导出word或pdf。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (334, 6, 2, 27, 320278, 346158, '01-0', 2, '第三，已完成任务不能再修改进度、延期转交或发送提醒，陈琳继续还需要在正式发布前补充两组验收数据，第一组是至少30分钟的真实会议录音，用于验证长音频切分、异步进度和长文本纪要合并。', '第三，已完成任务不能再修改进度、延期转交或发送提醒，陈琳继续还需要在正式发布前补充两组验收数据，第一组是至少30分钟的真实会议录音，用于验证长音频切分、异步进度和长文本纪要合并。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (335, 6, 2, 28, 346158, 356900, '01-0', 2, '第二组是包含多个角色发言的会议内容，用于检查说话人标签与员工身份的匹配效果。', '第二组是包含多个角色发言的会议内容，用于检查说话人标签与员工身份的匹配效果。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (336, 6, 2, 29, 356900, 369835, '01-0', 2, '今天的会议录音将作为演示素材之一，内容会包含产品研发、测试、运营和客户支持角色的发言。', '今天的会议录音将作为演示素材之一，内容会包含产品研发、测试、运营和客户支持角色的发言。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (337, 6, 2, 30, 369835, 397977, '01-0', 2, '主持人李月，下面讨论9月1日正式发布范围，张晨产品侧建议按既定范围发布，发布内容包括会议创建和状态流转、会议资料管理、音视频转写、AI纪要、任务跟踪、会议知识库react agent数据分析、运行观测和质量评价。', '主持人李月，下面讨论9月1日正式发布范围，张晨产品侧建议按既定范围发布，发布内容包括会议创建和状态流转、会议资料管理、音视频转写、AI纪要、任务跟踪、会议知识库react agent数据分析、运行观测和质量评价。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (338, 6, 2, 31, 397977, 412580, '01-0', 2, '移动端附件下载进度问题不影响核心会议和任务流程，但需要在发布前修复，并在发布说明中写明处理结果。', '移动端附件下载进度问题不影响核心会议和任务流程，但需要在发布前修复，并在发布说明中写明处理结果。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (339, 6, 2, 32, 412700, 429421, '01-0', 2, '运营负责人赵敏，运营册建议增加两个发布后的观察指标，第一个是员工从会议纪要创建正式任务的转化率，第二个是任务逾期率。', '运营负责人赵敏，运营册建议增加两个发布后的观察指标，第一个是员工从会议纪要创建正式任务的转化率，第二个是任务逾期率。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (340, 6, 2, 33, 429421, 440260, '01-0', 2, '上线后一周内，我们将按部门查看会议数量、会议时长、任务完成率、逾期率和高频一题。', '上线后一周内，我们将按部门查看会议数量、会议时长、任务完成率、逾期率和高频一题。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (341, 6, 2, 34, 440260, 446717, '01-0', 2, '对于逾期任务，负责人会在任务详情中看到提醒记录。', '对于逾期任务，负责人会在任务详情中看到提醒记录。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (342, 6, 2, 35, 446717, 462273, '01-0', 2, '运营同学每天下午四点汇总高风险任务，并同步给部门负责人、客户支持负责人周宁，客服侧关心知识问答的引用是否足够清晰。', '运营同学每天下午四点汇总高风险任务，并同步给部门负责人、客户支持负责人周宁，客服侧关心知识问答的引用是否足够清晰。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (343, 6, 2, 36, 462273, 482875, '01-0', 2, '我们希望用户在提问跨会议问题后，不只是看到答案，还要看到引用的会议名称、来源类型、时间点和原文片段，这样客服同学能够快速判断答案来自哪一场会议。', '我们希望用户在提问跨会议问题后，不只是看到答案，还要看到引用的会议名称、来源类型、时间点和原文片段，这样客服同学能够快速判断答案来自哪一场会议。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (344, 6, 2, 37, 482875, 503755, '01-0', 2, '王工，当前re返回结构已经包含这些信息，转写来源会显示时间点，纪要和附件来源会显示文件或纪要版本名称，前端会在回答下面展示引用依据和相似度。', '王工，当前re返回结构已经包含这些信息，转写来源会显示时间点，纪要和附件来源会显示文件或纪要版本名称，前端会在回答下面展示引用依据和相似度。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (345, 6, 2, 38, 503755, 507406, '01-0', 2, '主持人，李月，现在讨论风险？', '主持人，李月，现在讨论风险？', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (346, 6, 2, 39, 507406, 512717, '01-0', 2, '陈琳，第一项风险是模型服务延迟波动。', '陈琳，第一项风险是模型服务延迟波动。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (347, 6, 2, 40, 512717, 533684, '01-0', 2, '虽然调用失败可以重试，但在会议纪要生成和agent运行中，用户会看到等待时间，建议在发布首周每天查看运行观测中心的调用量、失败率、平均耗时和token使用量。', '虽然调用失败可以重试，但在会议纪要生成和agent运行中，用户会看到等待时间，建议在发布首周每天查看运行观测中心的调用量、失败率、平均耗时和token使用量。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (348, 6, 2, 41, 533684, 538064, '01-0', 2, '第二项风险是会议资料频繁更新。', '第二项风险是会议资料频繁更新。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (349, 6, 2, 42, 538064, 554167, '01-0', 2, '如果用户在知识索引构建过程中上传新附件或修订转写文本，索引状态会保持需要重建，建议资料整理完成后再发起构建。', '如果用户在知识索引构建过程中上传新附件或修订转写文本，索引状态会保持需要重建，建议资料整理完成后再发起构建。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (350, 6, 2, 43, 554167, 559296, '01-0', 2, '第三项风险是任务负责人分配不合理。', '第三项风险是任务负责人分配不合理。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (351, 6, 2, 44, 559296, 570194, '01-0', 2, 'Agent可以结合员工当前任务负载提出负责人建议，但创建正式任务前仍由用户确认。', 'Agent可以结合员工当前任务负载提出负责人建议，但创建正式任务前仍由用户确认。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (352, 6, 2, 45, 570194, 588629, '01-0', 2, '王工，我补充一个数据风险，删除用户时，如果该账号已经关联会议任务转写纪要知识问答，agent运行或质量评价记录，系统不会执行删除。', '王工，我补充一个数据风险，删除用户时，如果该账号已经关联会议任务转写纪要知识问答，agent运行或质量评价记录，系统不会执行删除。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (353, 6, 2, 46, 588629, 605260, '01-0', 2, '管理员需要先调整业务记录中的负责人、创建人或协作人关系，这样可以保证历史会议和任务记录仍能正确展示人员信息。', '管理员需要先调整业务记录中的负责人、创建人或协作人关系，这样可以保证历史会议和任务记录仍能正确展示人员信息。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (354, 6, 2, 47, 605260, 621840, '01-0', 2, '张晨，关于移动端下载进度研发计划今天下午完成接口和前端验证，负责人是王工，协作人是陈琳，截止时间为8月30日18点。', '张晨，关于移动端下载进度研发计划今天下午完成接口和前端验证，负责人是王工，协作人是陈琳，截止时间为8月30日18点。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (355, 6, 2, 48, 621840, 642802, '01-0', 2, '任务描述是在若网络条件下附件下载时，展示明确的下载状态和失败提示，并验证pdf、word音频和视频四类文件，请记要中记录未发布前阻断事项。', '任务描述是在若网络条件下附件下载时，展示明确的下载状态和失败提示，并验证pdf、word音频和视频四类文件，请记要中记录未发布前阻断事项。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (356, 6, 2, 49, 642802, 653084, '01-0', 2, '陈琳，我确认测试安排，测试团队将在8月31日中午12点前完成回归。', '陈琳，我确认测试安排，测试团队将在8月31日中午12点前完成回归。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (357, 6, 2, 50, 653084, 681753, '01-0', 2, '覆盖管理员和员工两种角色，重点检查登录注册部门员工权限、会议资料上传下载、长音频转写、纪要导出、任务确认、逾期提醒、知识索引重建、跨会议问答和agent人工确认完成后，会在发布群提交测试结论和任务完成凭证。', '覆盖管理员和员工两种角色，重点检查登录注册部门员工权限、会议资料上传下载、长音频转写、纪要导出、任务确认、逾期提醒、知识索引重建、跨会议问答和agent人工确认完成后，会在发布群提交测试结论和任务完成凭证。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (358, 6, 2, 51, 681753, 709926, '01-0', 2, '赵敏运营团队在9月1日九点前完成发布公告使用指引和部门通知负责人赵敏，协作人周宁，截止时间为9月1日九点，公告中需要包含会议创建入口、录音上传入口，既要确认入口、任务跟踪入口和知识库问答入口。', '赵敏运营团队在9月1日九点前完成发布公告使用指引和部门通知负责人赵敏，协作人周宁，截止时间为9月1日九点，公告中需要包含会议创建入口、录音上传入口，既要确认入口、任务跟踪入口和知识库问答入口。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (359, 6, 2, 52, 709926, 720120, '01-0', 2, '运营还会准备两场线上答疑，收集员工对转写质量、纪要质量和任务提醒的反馈。', '运营还会准备两场线上答疑，收集员工对转写质量、纪要质量和任务提醒的反馈。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (360, 6, 2, 53, 720120, 735498, '01-0', 2, '周宁客户支持团队在9月1日十点前完成常见问题知识库，负责人周宁，协作人赵敏，截止时间为9月1日十点。', '周宁客户支持团队在9月1日十点前完成常见问题知识库，负责人周宁，协作人赵敏，截止时间为9月1日十点。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (361, 6, 2, 54, 735498, 763809, '01-0', 2, '内容包括账号登录、会议权限、资料上传、格式转写失败、重试纪要导出任务负责人调整知识索引状态和agent人工确认，遇到无法复现的问题时，客服会记录会议编号、任务编号或agent运行编号，方便研发从运行记录追踪。', '内容包括账号登录、会议权限、资料上传、格式转写失败、重试纪要导出任务负责人调整知识索引状态和agent人工确认，遇到无法复现的问题时，客服会记录会议编号、任务编号或agent运行编号，方便研发从运行记录追踪。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (362, 6, 2, 55, 763809, 769240, '01-0', 2, '主持人李月请各负责人确认任务和期限。', '主持人李月请各负责人确认任务和期限。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (363, 6, 2, 56, 769240, 777000, '01-0', 2, '王工确认移动端附件下载进度任务8月30日18点完成。', '王工确认移动端附件下载进度任务8月30日18点完成。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (364, 6, 2, 57, 777000, 784140, '01-0', 2, '陈琳确认发布回归任务，8月31日中午12点完成。', '陈琳确认发布回归任务，8月31日中午12点完成。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (365, 6, 2, 58, 784140, 791280, '01-0', 2, '赵敏确认发布公告和部门通知任务9月1日九点完成。', '赵敏确认发布公告和部门通知任务9月1日九点完成。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (366, 6, 2, 59, 791280, 798144, '01-0', 2, '周宁确认常见问题知识库任务9月1日十点完成。', '周宁确认常见问题知识库任务9月1日十点完成。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (367, 6, 2, 60, 798144, 807623, '01-0', 2, '张晨负责发布决策复盘与首周数据汇总，截止时间为9月8日18点。', '张晨负责发布决策复盘与首周数据汇总，截止时间为9月8日18点。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (368, 6, 2, 61, 807623, 816204, '01-0', 2, '张晨首周复盘将重点看五项数据，第一，会议创建数量和总时长。', '张晨首周复盘将重点看五项数据，第一，会议创建数量和总时长。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (369, 6, 2, 62, 816204, 820876, '01-0', 2, '第二，转写任务成功率和平均耗时。', '第二，转写任务成功率和平均耗时。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (370, 6, 2, 63, 820876, 828218, '01-0', 2, '第三，已确认纪要数量、任务草稿数量和正式任务数量。', '第三，已确认纪要数量、任务草稿数量和正式任务数量。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (371, 6, 2, 64, 828218, 831889, '01-0', 2, '第四，任务完成率和逾期率。', '第四，任务完成率和逾期率。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (372, 6, 2, 65, 831889, 840900, '01-0', 2, '第五，rap问答调用量、agent运行次数、工具调用成功率和人工确认次数。', '第五，rap问答调用量、agent运行次数、工具调用成功率和人工确认次数。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (373, 6, 2, 66, 840900, 856942, '01-0', 2, '质量评价页面还会收集纪要和agent结果的综合评分，准确性、完整性和可执行性评分，用于观察模型输出是否满足业务需要。', '质量评价页面还会收集纪要和agent结果的综合评分，准确性、完整性和可执行性评分，用于观察模型输出是否满足业务需要。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (374, 6, 2, 67, 856942, 863360, '01-0', 2, '主持人，李月，关于正式发布决策，请大家最后确认。', '主持人，李月，关于正式发布决策，请大家最后确认。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (375, 6, 2, 68, 863360, 879115, '01-0', 2, '产品研发、测试、运营和客户支持均同意在9月1日九点按计划发布，前提是移动端附件下载进度任务和发布回归任务按时完成。', '产品研发、测试、运营和客户支持均同意在9月1日九点按计划发布，前提是移动端附件下载进度任务和发布回归任务按时完成。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (376, 6, 2, 69, 879115, 892699, '01-0', 2, '如果任意阻断任务没有完成，由张晨和王工在8月31日下午五点召开专项评审，决定是否调整发布时间。', '如果任意阻断任务没有完成，由张晨和王工在8月31日下午五点召开专项评审，决定是否调整发布时间。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (377, 6, 2, 70, 892699, 900648, '01-0', 2, '这个条件请记录未会议该确认事项同时记录风险等级为高。', '这个条件请记录未会议该确认事项同时记录风险等级为高。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (378, 6, 2, 71, 900648, 903828, '01-0', 2, '最后总结本次会议决策。', '最后总结本次会议决策。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (379, 6, 2, 72, 903828, 911460, '01-0', 2, '第一，9月1日九点发布AI智能会议助手与任务跟踪系统。', '第一，9月1日九点发布AI智能会议助手与任务跟踪系统。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (380, 6, 2, 73, 911460, 926376, '01-0', 2, '第二，移动端附件下载进度发布回归、发布公告、客服常见问题和首周数据复盘五项任务按已确认负责人和期限执行。', '第二，移动端附件下载进度发布回归、发布公告、客服常见问题和首周数据复盘五项任务按已确认负责人和期限执行。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (381, 6, 2, 74, 926376, 935700, '01-0', 2, '第三，知识索引构建期间资料变化时，由资料维护人完成整理后重新构建。', '第三，知识索引构建期间资料变化时，由资料维护人完成整理后重新构建。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (382, 6, 2, 75, 935720, 952520, '01-0', 2, '第四，发布首周，每天查看运行观测和质量评价数据，发现任务逾期、模型调用失败率升高或员工反馈集中时，及时形成跟进报告。', '第四，发布首周，每天查看运行观测和质量评价数据，发现任务逾期、模型调用失败率升高或员工反馈集中时，及时形成跟进报告。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (383, 6, 2, 76, 952520, 956720, '01-0', 2, '今天会议到这里结束，感谢大家。', '今天会议到这里结束，感谢大家。', NULL, NULL, '2026-09-16 02:29:22', '2026-09-16 02:32:38');
INSERT INTO `transcript_segment` VALUES (384, 7, 2, 1, 0, 3952, '01-0', 1, '各位下午好，今天的产品发布评审会现在开始。', '各位下午好，今天的产品发布评审会现在开始。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (385, 7, 2, 2, 3952, 7904, '01-0', 1, '今天要出三个结论，V2.0能不能按期发布？', '今天要出三个结论，V2.0能不能按期发布？', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (386, 7, 2, 3, 7904, 8944, '01-0', 1, '灰度怎么放？', '灰度怎么放？', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (387, 7, 2, 4, 8944, 11440, '01-0', 1, '还有对外通稿什么时候定稿？', '还有对外通稿什么时候定稿？', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (388, 7, 2, 5, 11600, 15032, '01-0', 1, '先请王敏说一下功能验收的情况。', '先请王敏说一下功能验收的情况。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (389, 7, 2, 6, 15032, 26800, '01-1', 2, '好的，V2.0计划内的17个需求已经验收通过15个，剩下两个，一个是报表导出，一个是消息推送的免打扰设置。', '好的，V2.0计划内的17个需求已经验收通过15个，剩下两个，一个是报表导出，一个是消息推送的免打扰设置。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:31');
INSERT INTO `transcript_segment` VALUES (390, 7, 2, 7, 26800, 31617, '01-1', 2, '消息推送这个已经修完了，昨天回归通过报表导出。', '消息推送这个已经修完了，昨天回归通过报表导出。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:31');
INSERT INTO `transcript_segment` VALUES (391, 7, 2, 8, 31617, 35287, '01-1', 2, '还有问题我让张涛详细说一下报表导。', '还有问题我让张涛详细说一下报表导。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:31');
INSERT INTO `transcript_segment` VALUES (392, 7, 2, 9, 35287, 38269, '01-2', 2, '出的问题在压测里暴露出来了。', '出的问题在压测里暴露出来了。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:23');
INSERT INTO `transcript_segment` VALUES (393, 7, 2, 10, 38269, 45840, '01-2', 2, '单个用户导出三个月的数据接口要跑四十多秒，超过了网关30秒的超时限制。', '单个用户导出三个月的数据接口要跑四十多秒，超过了网关30秒的超时限制。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:23');
INSERT INTO `transcript_segment` VALUES (394, 7, 2, 11, 46000, 52540, '01-2', 2, '我们压了500并发，这个接口的失败率到了12%，其他接口都是正常的。', '我们压了500并发，这个接口的失败率到了12%，其他接口都是正常的。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:23');
INSERT INTO `transcript_segment` VALUES (395, 7, 2, 12, 52700, 58420, '01-0', 1, '四十多秒确实不能接受，有没有办法在发布前解决？', '四十多秒确实不能接受，有没有办法在发布前解决？', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (396, 7, 2, 13, 58480, 67660, '01-2', 2, '有两个方案，一是加缓存，把常用的时间范围预生成，但覆盖不全，用户选个冷门区间还是慢。', '有两个方案，一是加缓存，把常用的时间范围预生成，但覆盖不全，用户选个冷门区间还是慢。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:23');
INSERT INTO `transcript_segment` VALUES (397, 7, 2, 14, 67820, 77160, '01-2', 2, '二是改成异步任务，用户点导出之后先返回一个任务号，后台跑完了再通知他下载这个方案彻底一些。', '二是改成异步任务，用户点导出之后先返回一个任务号，后台跑完了再通知他下载这个方案彻底一些。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:23');
INSERT INTO `transcript_segment` VALUES (398, 7, 2, 15, 77280, 87300, '01-1', 2, '从用户体验看，异步方案更好导出本来就是个低频操作，等一会儿可以接受卡在那转圈40秒反而更差。', '从用户体验看，异步方案更好导出本来就是个低频操作，等一会儿可以接受卡在那转圈40秒反而更差。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:31');
INSERT INTO `transcript_segment` VALUES (399, 7, 2, 16, 87300, 89476, '01-0', 1, '异步方案要改多久？', '异步方案要改多久？', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (400, 7, 2, 17, 89476, 94916, '01-2', 2, '涉及三个服务，导出服务、任务调度，还有消息通知。', '涉及三个服务，导出服务、任务调度，还有消息通知。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:23');
INSERT INTO `transcript_segment` VALUES (401, 7, 2, 18, 94916, 99540, '01-2', 2, '开发两天，连调一天，测试两天，加起来一周。', '开发两天，连调一天，测试两天，加起来一周。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:23');
INSERT INTO `transcript_segment` VALUES (402, 7, 2, 19, 99720, 109420, '01-0', 1, '那就定一步方案发布时间不变，报表导出这个功能在发布时先隐藏入口，等改造完成再单独放出来。', '那就定一步方案发布时间不变，报表导出这个功能在发布时先隐藏入口，等改造完成再单独放出来。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (403, 7, 2, 20, 109480, 113094, '01-2', 2, '明白，我这边今天就拆任务。', '明白，我这边今天就拆任务。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:23');
INSERT INTO `transcript_segment` VALUES (404, 7, 2, 21, 113094, 116380, '01-0', 1, '陈磊说一下灰度和容量。', '陈磊说一下灰度和容量。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (405, 7, 2, 22, 116460, 118049, '01-3', 3, '容量这块没问题。', '容量这块没问题。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:32');
INSERT INTO `transcript_segment` VALUES (406, 7, 2, 23, 118049, 124860, '01-3', 3, '现在的机器配置扛刀日活8万枚压力我们预估发布后日或是5万左右。', '现在的机器配置扛刀日活8万枚压力我们预估发布后日或是5万左右。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:32');
INSERT INTO `transcript_segment` VALUES (407, 7, 2, 24, 124860, 142420, '01-3', 3, '灰度方案我建议分三步，第一天放10%观察一天，第二天到50%，第三天全量回滚预案也准备好了，数据库改动都是加字段向后兼容，回滚步需要动数据，最快五分钟能切回旧版本。', '灰度方案我建议分三步，第一天放10%观察一天，第二天到50%，第三天全量回滚预案也准备好了，数据库改动都是加字段向后兼容，回滚步需要动数据，最快五分钟能切回旧版本。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:32');
INSERT INTO `transcript_segment` VALUES (408, 7, 2, 25, 142420, 145588, '01-0', 1, '第一天10%是按什么维度切？', '第一天10%是按什么维度切？', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (409, 7, 2, 26, 145588, 151926, '01-3', 3, '挨用户ID取魔，保证同一个用户每次都落在同一边，不会一会儿新版。', '挨用户ID取魔，保证同一个用户每次都落在同一边，不会一会儿新版。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:32');
INSERT INTO `transcript_segment` VALUES (410, 7, 2, 27, 151926, 153057, '01-1', 2, '一会儿旧版。', '一会儿旧版。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:31');
INSERT INTO `transcript_segment` VALUES (411, 7, 2, 28, 153057, 156000, '01-1', 2, '灰度期间我们需要盯哪些指标？', '灰度期间我们需要盯哪些指标？', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:31');
INSERT INTO `transcript_segment` VALUES (412, 7, 2, 29, 156000, 161280, '01-3', 3, '主要看接口错误率、平均响应时间，还有核心链路的转化率。', '主要看接口错误率、平均响应时间，还有核心链路的转化率。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:32');
INSERT INTO `transcript_segment` VALUES (413, 7, 2, 30, 161280, 164140, '01-3', 3, '这三个我配了告警，超过阈值会。', '这三个我配了告警，超过阈值会。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:32');
INSERT INTO `transcript_segment` VALUES (414, 7, 2, 31, 164140, 165460, '01-0', 1, '直接发到群里。', '直接发到群里。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (415, 7, 2, 32, 165460, 169860, '01-0', 1, '灰度这三天需要有人值班盯盘，这个排班定了吗？', '灰度这三天需要有人值班盯盘，这个排班定了吗？', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (416, 7, 2, 33, 170000, 175291, '01-3', 3, '还没排，我明天下班前把排班表发到群里。', '还没排，我明天下班前把排班表发到群里。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:32');
INSERT INTO `transcript_segment` VALUES (417, 7, 2, 34, 175291, 177781, '01-0', 1, '好，这是一个行动项。', '好，这是一个行动项。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (418, 7, 2, 35, 177781, 179960, '01-0', 1, '刘颖市场这边呢。', '刘颖市场这边呢。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (419, 7, 2, 36, 180060, 186740, '01-4', 1, '对外通稿的初稿已经写完了，还需要根据最终的功能清单调整报表导出。', '对外通稿的初稿已经写完了，还需要根据最终的功能清单调整报表导出。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:34');
INSERT INTO `transcript_segment` VALUES (420, 7, 2, 37, 186740, 190080, '01-4', 1, '既然要隐藏，那通稿里这一段要删掉。', '既然要隐藏，那通稿里这一段要删掉。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:34');
INSERT INTO `transcript_segment` VALUES (421, 7, 2, 38, 190140, 195540, '01-4', 1, '另外我想确认发布当天要不要同步发一条产品公告。', '另外我想确认发布当天要不要同步发一条产品公告。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:34');
INSERT INTO `transcript_segment` VALUES (422, 7, 2, 39, 195640, 201020, '01-0', 1, '发公告和通告一起都放在发布当天上午十点。', '发公告和通告一起都放在发布当天上午十点。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (423, 7, 2, 40, 201160, 205720, '01-4', 1, '那我需要在发布前一天定稿留出审核时间。', '那我需要在发布前一天定稿留出审核时间。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:34');
INSERT INTO `transcript_segment` VALUES (424, 7, 2, 41, 205820, 211120, '01-0', 1, '可以通稿，定稿时间就定在发布前一日下午六点前。', '可以通稿，定稿时间就定在发布前一日下午六点前。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (425, 7, 2, 42, 211280, 220640, '01-2', 2, '还有个风险我要提一下，异步改造和灰度发布挨得太近，如果改造延期可能会影响到后面的排期。', '还有个风险我要提一下，异步改造和灰度发布挨得太近，如果改造延期可能会影响到后面的排期。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:23');
INSERT INTO `transcript_segment` VALUES (426, 7, 2, 43, 220980, 222431, '01-0', 1, '这个风险记下来。', '这个风险记下来。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (427, 7, 2, 44, 222431, 230520, '01-0', 1, '张涛，你这周三给我一个中期进度，如果到周三还没完成联调，我们就把报表导出推到下个版本。', '张涛，你这周三给我一个中期进度，如果到周三还没完成联调，我们就把报表导出推到下个版本。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (428, 7, 2, 45, 230640, 232343, '01-2', 2, '行，周三给进度。', '行，周三给进度。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:23');
INSERT INTO `transcript_segment` VALUES (429, 7, 2, 46, 232343, 233762, '01-2', 2, '那今天的结。', '那今天的结。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 10:33:23');
INSERT INTO `transcript_segment` VALUES (430, 7, 2, 47, 233762, 240860, '01-0', 1, '论我复述一遍，第一，V2.0按期发布，报表导出入口先隐藏。', '论我复述一遍，第一，V2.0按期发布，报表导出入口先隐藏。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (431, 7, 2, 48, 240960, 245787, '01-0', 1, '第二，灰度按10%、50%全量分三天走。', '第二，灰度按10%、50%全量分三天走。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
INSERT INTO `transcript_segment` VALUES (432, 7, 2, 49, 245787, 257240, '01-0', 1, '第三，对外通稿和产品公告在发布前一日下午六点前定稿行动项有三个，张涛负责报表导出异步化改造，本周五前完成。', '第三，对外通稿和产品公告在发布前一日下午六点前定稿行动项有三个，张涛负责报表导出异步化改造，本周五前完成。', NULL, NULL, '2026-09-16 02:30:09', '2026-09-16 02:33:22');
